import { writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const assetLocale = (locale) => locale === 'zh_Hans' ? 'zh-hans' : locale;
const figure = (locale, area, file, alt, caption) => `<figure class="screenshot"><img src="/images/docs/${assetLocale(locale)}/${area}/${file}" alt="${alt}" class="screenshot__img" loading="lazy"><figcaption class="screenshot__caption">${caption}</figcaption></figure>`;
const body = (sections) => sections.map(({ id, title, html }) => `<h2 id="${id}">${title}</h2>${html}`).join('');
const documentFor = ({ title, heading, lead, sections }) => ({ title, hero: { heading, lead, eyebrow: null, chips: [] }, body: body(sections) });

const localized = {
  de: {
    training: {
      title: 'Trainingsplanung – Kaderblick-Dokumentation', heading: 'Training vollständig planen, durchführen und auswerten', lead: 'Ziele, Ablauf, Mannschaft, Saison und Nachbereitung in zusammenhängenden Arbeitswegen bearbeiten.',
      sections: [
        { id: 'entry-context', title: 'Training öffnen, Kontext prüfen und Arbeitsweg verstehen', html: `<p>Die Trainingsplanung erweitert immer einen vorhandenen Kalendertermin. Öffne das Training im <strong>Kalender</strong> und wähle <strong>Training planen</strong>, <strong>Planung öffnen</strong> oder – bei einer vorbereiteten Einheit – <strong>Durchführen</strong>. Dadurch bleiben Termin, Teilnahme und Planung miteinander verbunden.</p><ol><li>Prüfe im Kopf Mannschaft, Datum, Uhrzeit und Spielstätte.</li><li>Prüfe den Status <strong>Entwurf</strong>, <strong>Bereit</strong> oder <strong>Abgeschlossen</strong>.</li><li>Bearbeite die Planung in der Reihenfolge <strong>Ziel</strong>, <strong>Ablauf</strong>, <strong>Mannschaft</strong> und <strong>Abschluss</strong>. Auf dem Smartphone zeigt eine Fortschrittsanzeige den aktuellen Schritt.</li><li>Verlasse die Seite bei ungespeicherten Änderungen nur nach der eingeblendeten Bestätigung.</li></ol><p>Fehlt die Planungsaktion, besitzt dein Konto entweder kein Bearbeitungsrecht für dieses Training oder der Termin ist nicht mehr planbar.</p>${figure('de','training-planning','overview.png','Geöffneter Trainingstermin mit Aktion zur Trainingsplanung','Die Planung wird am vorhandenen Training geöffnet; es entsteht kein zweiter Termin.')}` },
        { id: 'goals-templates', title: 'Ziele, Vorbereitung, Saisonbezug und Vorlagen festlegen', html: `<p>Im Schritt <strong>Ziel</strong> entsteht die fachliche Grundlage der Einheit.</p><ol><li>Trage einen eindeutigen <strong>Schwerpunkt</strong> und ein konkretes <strong>Gesamtziel</strong> ein.</li><li>Ergänze in der Vorbereitungsnotiz alles, was vor Beginn geklärt oder aufgebaut werden muss.</li><li>Ordne vorhandene Saisonziele zu. Die Zuordnung verbindet die Einheit mit der Saisonplanung; sie verändert das Saisonziel nicht.</li><li>Wähle bei Bedarf eine Mannschaftsvorlage. Prüfe vor <strong>Anwenden</strong> Name und Inhalt.</li></ol><p>Eine angewendete Vorlage wird als unabhängige Kopie übernommen. Spätere Änderungen an der Einheit verändern weder die Vorlage noch andere Trainings. Eigene Planungen lassen sich als neue Vorlage speichern; vorhandene Vorlagen können umbenannt oder archiviert werden. Das Anwenden, Erstellen und Ändern von Vorlagen benötigt eine Online-Verbindung.</p>${figure('de','training-planning','editor.png','Erster Schritt der Trainingsplanung mit Zielen und Vorlagen','Im ersten Schritt werden Ziel, Vorbereitung, Saisonbezug und eine mögliche Vorlage festgelegt.')}` },
        { id: 'schedule-exercises', title: 'Ablaufblöcke, Material und Übungsbibliothek verwenden', html: `<p>Im Schritt <strong>Ablauf</strong> legst du die Reihenfolge der Einheit fest.</p><ol><li>Füge einen Block hinzu und erfasse Titel, Dauer, Intensität, Ziel und Anleitung.</li><li>Verschiebe Blöcke mit den sichtbaren Aktionen nach oben oder unten. Du kannst einen Block außerdem duplizieren oder entfernen.</li><li>Ergänze Material mit Bezeichnung und Menge. Entferne nicht benötigte Positionen wieder.</li><li>Vergleiche die geplante Gesamtdauer mit der Dauer des Kalendertermins.</li></ol><h3>Übungen übernehmen</h3><p>Öffne die <strong>Übungsbibliothek</strong>, suche nach Name oder Inhalt und grenze bei Bedarf nach Mannschaft, Verein, Altersgruppe oder Spielerzahl ein. Öffne eine Übung, prüfe Ziel, Anleitung, Dauer, Material und vorhandenen Platzaufbau und übernimm sie anschließend in den Ablauf. Berechtigte Trainer können eigene Übungen anlegen oder bearbeiten sowie geeignete Volleyballübungen in die gemeinsame Bibliothek kopieren. Bei einem Änderungskonflikt lädst du zuerst den aktuellen Stand neu.</p>${figure('de','training-planning','exercise-library.png','Übungsbibliothek mit Suche und Übungsdetails','Die Bibliothek liefert vollständige Übungen und übernimmt sie als bearbeitbaren Ablaufblock.')}` },
        { id: 'setup', title: 'Grafischen Platzaufbau erstellen und in der Durchführung nutzen', html: `<p>Jeder Ablaufblock kann einen eigenen Platzaufbau erhalten. Öffne am Block <strong>Platzaufbau planen</strong> beziehungsweise <strong>Platzaufbau bearbeiten</strong>.</p><ol><li>Wähle die passende Spielfeld- oder Hallengrundlage.</li><li>Füge Spieler, Trainer, Tore, Hütchen, Bälle und weitere Symbole aus der Werkzeugleiste ein.</li><li>Verschiebe und bearbeite ausgewählte Elemente; ergänze Beschriftungen, Wege und Bewegungsrichtungen.</li><li>Nutze Rückgängig und Wiederholen, wenn ein Bearbeitungsschritt korrigiert werden soll.</li><li>Prüfe Legende und Beschreibung und speichere den Aufbau am Block.</li></ol><p>Die Tastaturhilfe erklärt die verfügbaren Bedienungen. Während der Durchführung ist der gespeicherte Aufbau schreibgeschützt verfügbar, damit die Organisation auf dem Platz ohne Wechsel in den Editor nachvollziehbar bleibt.</p>${figure('de','training-planning','setup.png','Editor für den grafischen Platzaufbau eines Trainingsblocks','Symbole, Wege und Beschriftungen erklären den Aufbau direkt am zugehörigen Block.')}` },
        { id: 'team-publication', title: 'Teilnahme einordnen und Spieler gezielt informieren', html: `<p>Im Schritt <strong>Mannschaft</strong> stehen interne Planung und veröffentlichte Spielerinformation nebeneinander, bleiben aber bewusst getrennt.</p><h3>Teilnahmeübersicht</h3><p>Die Übersicht unterscheidet Zusagen, Vielleicht, Absagen und offene Rückmeldungen. Nutze sie zur Anpassung der Übungsauswahl und Gruppengröße. Kann die Übersicht nicht geladen werden, zeigt Kaderblick einen Fehler mit erneutem Laden; ein Ladefehler wird nicht als leere Mannschaft dargestellt.</p><h3>Spielerinformation</h3><ol><li>Formuliere das sichtbare Trainingsziel.</li><li>Ergänze Treffpunkt beziehungsweise Treffzeit, mitzubringende Dinge und weitere Hinweise.</li><li>Prüfe die Vorschau aus Spielersicht.</li><li>Wähle <strong>Veröffentlichen</strong>. Interne Trainerhinweise und Ablaufdetails werden dadurch nicht automatisch freigegeben.</li></ol><p>Änderungen können erneut veröffentlicht, eine Veröffentlichung kann zurückgezogen werden. Bei einem gleichzeitigen Bearbeitungskonflikt wird nicht still überschrieben; lade den aktuellen Stand und entscheide erneut.</p>${figure('de','training-planning','team.png','Mannschaftsschritt mit Teilnahmeübersicht und Spielerinformation','Rückmeldungen unterstützen die Planung; veröffentlicht werden nur ausdrücklich ausgewählte Informationen.')}` },
        { id: 'week-series', title: 'Trainingswoche überblicken und einen Plan auf Serientermine übertragen', html: `<h3>Wochenübersicht</h3><p>Öffne im Abschlussbereich die Trainingswoche. Wechsle zur vorherigen, aktuellen oder nächsten Woche und prüfe pro Termin, ob noch keine Planung, ein Entwurf, eine bereite oder eine abgeschlossene Planung vorliegt. Mit <strong>Planung öffnen</strong> wechselst du direkt zur ausgewählten Einheit.</p><h3>Serienübertragung</h3><p>Bei einem Training aus einer Terminserie steht <strong>Auf Serie übertragen</strong> zur Verfügung, sobald der aktuelle Entwurf gespeichert ist.</p><ol><li>Öffne die Vorschau.</li><li>Prüfe jeden Zieltermin und vorhandene Planungsstände.</li><li>Wähle nur die Termine aus, die den Plan erhalten sollen.</li><li>Bestätige die Übertragung und kontrolliere das Ergebnis je Termin.</li></ol><p>Vorhandene Zielplanungen, übersprungene Termine und Konflikte werden einzeln ausgewiesen. Die Übertragung ist kein pauschales Überschreiben der gesamten Serie.</p>${figure('de','training-planning','tools.png','Abschlussbereich mit Wochenübersicht und Serienwerkzeugen','Wochen- und Serienfunktionen verbinden einzelne Einheiten, ohne bestehende Planungen unbemerkt zu ersetzen.')}` },
        { id: 'season-collaboration', title: 'Saisonphasen, messbare Ziele und Zusammenarbeit pflegen', html: `<h3>Saisonplanung</h3><ol><li>Öffne den Saisonplan der Mannschaft.</li><li>Lege Titel, Beginn und Ende fest.</li><li>Erfasse Phasen mit Zeitraum und Schwerpunkt.</li><li>Lege Ziele mit Beschreibung, Zieldatum und geeigneter Messung an. Je nach Ziel können Trainingsbeobachtungen, Bewertungsstufen oder Wettbewerbswerte verwendet werden.</li><li>Dokumentiere Zwischenstände und prüfe den Fortschritt.</li><li>Speichere. Bei zwischenzeitlichen Änderungen anderer Personen lädst du den aktuellen Stand statt ihn zu überschreiben.</li></ol><h3>Zusammenarbeit</h3><p>In einer gespeicherten, noch nicht abgeschlossenen Planung kannst du Mitwirkende mit Verantwortung als Leitung, Assistenz oder Aufbau zuordnen. Ergänze Kommentare für Absprachen und nutze den Verlauf, um Erstellung, Änderungen, Freigaben, Veröffentlichungen, Vorlagen und Serienübertragungen nachzuvollziehen. Entferne Mitwirkende nur bewusst; Kommentare und Historie bleiben Teil der Planung.</p>${figure('de','training-planning','season.png','Saisonplanung mit Phasen, Zielen und Fortschritt','Saisonziele geben einzelnen Trainings einen nachvollziehbaren längerfristigen Bezug.')}` },
        { id: 'run-offline', title: 'Einheit mobil durchführen und Offline-Änderungen synchronisieren', html: `<p>Markiere die Planung erst als <strong>Bereit</strong>, wenn Schwerpunkt und mindestens ein Ablaufblock vorhanden sind. Weicht die Gesamtdauer vom Kalendertermin ab, zeigt Kaderblick die Differenz und verlangt eine bewusste Bestätigung.</p><ol><li>Öffne <strong>Durchführen</strong>.</li><li>Prüfe Termin- und Mannschaftskontext sowie den Fortschritt.</li><li>Lies Ziel, Anleitung, Dauer und gegebenenfalls den Platzaufbau des aktuellen Blocks.</li><li>Notiere Abweichungen und markiere den Block als erledigt.</li><li>Wechsle mit <strong>Vorheriger</strong> und <strong>Nächster</strong> durch die Einheit.</li></ol><p>Fällt die Verbindung während der Durchführung aus, bleibt die zwischengespeicherte Einheit bedienbar. Kaderblick kennzeichnet den Offline-Zustand. Nach Wiederherstellung der Verbindung werden Änderungen synchronisiert. Wurde die Planung inzwischen anderweitig geändert, erscheint ein Synchronisierungskonflikt: Entscheide ausdrücklich, ob du die Offline-Änderungen verwirfst oder anwendest. Der Abschluss einer Einheit benötigt eine Online-Verbindung und darf keine noch wartenden Änderungen besitzen.</p>${figure('de','training-planning','run-mobile.png','Mobile Durchführung mit aktuellem Block und Fortschritt','Die mobile Ansicht konzentriert sich auf den aktuellen Block, seine Anleitung und den sicheren Fortschritt.')}` },
        { id: 'review-analytics', title: 'Einheit abschließen, als PDF verwenden und auswerten', html: `<p>Beim Abschluss erfasst du eine interne Nachbereitung. Die Zusammenfassung unterscheidet geplante, erledigte und ausgelassene Blöcke. Eine abgeschlossene Einheit ist nicht mehr normal bearbeitbar, kann aber nach Bestätigung wieder geöffnet werden.</p><ul><li><strong>Ablaufplan drucken / PDF:</strong> öffnet den authentifiziert erzeugten Ablaufplan für Vorbereitung oder Ausdruck.</li><li><strong>Als Vorlage speichern:</strong> übernimmt eine geeignete Planung als neue, künftig unabhängig nutzbare Vorlage.</li><li><strong>Auswertungen:</strong> zeigen verwendete Schwerpunkte, Abweichungen, Vorlagennutzung und wiederverwendbare Einheiten im berechtigten Mannschaftskontext.</li><li><strong>Wiederverwendbare Einheit öffnen:</strong> führt zur zugrunde liegenden Planung; sie wird nicht unbemerkt kopiert.</li></ul><p>Auswertungen verwenden nur Daten, die dein Konto im jeweiligen Mannschaftskontext sehen darf. Ein leerer Auswertungsstand ist von einem Ladefehler unterscheidbar.</p>${figure('de','training-planning','analytics.png','Trainingsauswertung mit Schwerpunkten und wiederverwendbaren Einheiten','Die Auswertung hilft bei der Wiederverwendung, ohne interne Planungsdaten anderer Mannschaften offenzulegen.')}` },
        { id: 'troubleshooting', title: 'Berechtigungen, Ladefehler und Konflikte sicher behandeln', html: `<ul><li><strong>Planung fehlt:</strong> Prüfe Terminart, Mannschaft, Terminstatus und dein Bearbeitungsrecht. Erzeuge keinen zweiten Kalendertermin.</li><li><strong>Termin abgesagt oder gelöscht:</strong> Kehre zum Kalender zurück und prüfe den aktuellen Status. Eine Planung ohne verfügbaren Ursprungstermin kann nicht weitergeführt werden.</li><li><strong>Änderungskonflikt:</strong> Lade den aktuellen Stand. Übernimm deine Änderung anschließend bewusst erneut; Kaderblick überschreibt keine neuere Version still.</li><li><strong>Vorlage oder Übung fehlt:</strong> Prüfe Mannschaft, Verein, Sportart, Filter und Archivstatus.</li><li><strong>Saisonwerkzeuge fehlen:</strong> Prüfe Mannschaftskontext und Berechtigung. Serienwerkzeuge erscheinen nur bei einem Serientermin und nach gespeichertem Entwurf.</li><li><strong>Spieler sehen keine Information:</strong> Prüfe, ob die Spielerinformation tatsächlich veröffentlicht wurde. Das Speichern des internen Entwurfs reicht nicht.</li><li><strong>Offline-Abschluss gesperrt:</strong> Stelle die Verbindung wieder her und löse ausstehende Synchronisierung oder Konflikte.</li><li><strong>Laden oder PDF schlägt fehl:</strong> Nutze <strong>Erneut versuchen</strong>. Ein Fehler wird nicht durch eine leere Inhaltsfläche ersetzt.</li></ul><p>Bearbeiten, Veröffentlichen, Mitwirkende verwalten und Saisonplanung können unterschiedliche Rechte erfordern. Dass eine Planung sichtbar ist, belegt daher nicht automatisch ein Änderungsrecht.</p>` },
      ],
    },
    occupancy: {
      title: 'Platzbelegung – Kaderblick-Dokumentation', heading: 'Platzbelegung prüfen und Konflikte lösen', lead: 'Wochen- und Saisonbelegung verstehen, Platzbereiche korrekt buchen und Überschneidungen nachvollziehbar bearbeiten.',
      sections: [
        { id: 'choose-view', title: 'Ansicht, Zeitraum, Terminart und Spielstätten auswählen', html: `<p>Öffne <strong>Platzbelegung</strong>. Die Ansicht verwendet vorhandene Kalendertermine und legt keine zweite Terminverwaltung an.</p><ol><li>Wähle <strong>Woche</strong> für die operative Abstimmung oder <strong>Saison</strong> für einen längeren Zeitraum.</li><li>Filtere nach allen Belegungen, Spielen oder Trainings.</li><li>Wähle die Heimspielstätten beziehungsweise Sportflächen. Eine Suche beginnt ab zwei Zeichen und zeigt zur Unterscheidung Anlage, Fläche und Adresse.</li><li>In der Wochenansicht kannst du höchstens vier Flächen vergleichen. Die Saisonansicht erlaubt <strong>Alle Heimspielstätten</strong> und <strong>Auswahl löschen</strong>.</li></ol><p>Die Auswahl wird getrennt für Wochen- und Saisonansicht im Browser gespeichert. Ist genau eine Standard-Heimspielstätte vorhanden, wird sie zunächst vorausgewählt. Ladezustände und Fehler bleiben sichtbar; keine Auswahl wird nicht als freie Belegung missverstanden.</p>${figure('de','location-occupancy','overview.png','Wochenansicht der Platzbelegung mit ausgewählten Heimspielstätten','Filter und Spielstättenauswahl bestimmen, welche Kalenderbelegungen miteinander verglichen werden.')}` },
        { id: 'week-view', title: 'Wochenbelegung nach Tag, Fläche und Bereich lesen', html: `<p>Mit den Pfeilen wechselst du wochenweise, <strong>Aktuelle Woche</strong> führt zum heutigen Zeitraum zurück. Jeder Wochentag zeigt je ausgewählter Fläche freie Zeiten oder vorhandene Belegungen.</p><ul><li>Spiele zeigen Uhrzeit, Paarung und Wettbewerb.</li><li>Trainings zeigen Titel beziehungsweise Mannschaft und den zugewiesenen Platzbereich.</li><li>Weitere Termine verwenden ihre Terminart und hinterlegte Farbe.</li><li>Private Belegungen werden ohne vertraulichen Titel als <strong>Private Belegung</strong> dargestellt.</li><li>Die Aufbauzeit beginnt vor dem eigentlichen Termin und wird bei der Überschneidungsprüfung berücksichtigt.</li></ul><p>Ein Platz kann als Ganzes, Hälfte oder – bei entsprechend eingerichteten Flächen – über einzelne Segmente A, B und C belegt sein. Mehrere ausgewählte Segmente werden gemeinsam angezeigt.</p>` },
        { id: 'season-view', title: 'Saisonbelegung und auffällige Tage auswerten', html: `<p>Lege <strong>Von</strong> und <strong>Bis</strong> fest. Die Kennzahlen zeigen sämtliche Belegungen, Spiele, Trainings und die Zahl der Tage mit Prüfbedarf. Darunter werden die Termine nach Spielstätte und Datum sortiert.</p><p>Auf dem Desktop stehen Zeit, Belegung, Beteiligte sowie Bereich und Status in getrennten Spalten. Auf dem Smartphone erscheinen dieselben Angaben als kompakte Karten; es gehen keine Konflikthinweise verloren. Nutze den Prüfbedarf als Einstieg in die Detailkontrolle, nicht als automatische Fehlerkorrektur.</p>${figure('de','location-occupancy','season.png','Saisonansicht mit Kennzahlen und nach Spielstätte gruppierten Belegungen','Die Saisonansicht macht Auslastung und Tage mit Abstimmungsbedarf über einen frei gewählten Zeitraum sichtbar.')}` },
        { id: 'conflicts', title: 'Überschneidungen, Abstimmungsbedarf und Kapazitätskonflikte verstehen', html: `<p>Bei einer zeitlichen Überschneidung zeigt Kaderblick beide betroffenen Belegungen, den gemeinsamen Zeitraum und die ermittelte Ursache.</p><ul><li><strong>Bereich fehlt:</strong> Mindestens ein Termin besitzt keinen eindeutigen Platzbereich.</li><li><strong>Hälfte nicht festgelegt:</strong> Es ist nur „halber Platz“ hinterlegt, aber nicht welche Hälfte.</li><li><strong>Ganzer Platz:</strong> Eine parallele Nutzung kollidiert mit einer Vollbelegung.</li><li><strong>Gleicher Bereich:</strong> Zwei Termine beanspruchen dasselbe Segment.</li><li><strong>Kapazität überschritten:</strong> Die gleichzeitig beanspruchten Einheiten übersteigen die konfigurierte Teilbarkeit der Fläche.</li></ul><p>Ein gelber Hinweis bedeutet, dass eine Abstimmung oder genauere Zuordnung erforderlich ist. Ein roter Konflikt bezeichnet eine nach den vorhandenen Angaben nicht gleichzeitig mögliche Belegung. Korrigiere den zugrunde liegenden Kalendertermin; die Platzbelegung selbst besitzt keinen separaten Lösch- oder Verschiebevorgang.</p>${figure('de','location-occupancy','conflict.png','Zwei überschneidende Belegungen mit Ursache und Zeitraum','Der Konfliktblock stellt beide Termine und die konkrete Ursache gemeinsam dar.')}` },
        { id: 'event-booking', title: 'Platzbereich und Aufbauzeit am Kalendertermin pflegen', html: `<p>Wähle beim Anlegen oder Bearbeiten eines Trainings die Spielstätte. Danach erscheint die Belegungsprüfung direkt im Termindialog.</p><ol><li>Wähle bei teilbaren Flächen die benötigten Segmente. Bei einer Fläche ohne benannte Segmente wählst du halben oder ganzen Platz.</li><li>Öffne die Aufbauzeit und erfasse die Minuten vor Trainingsbeginn. Der Wert der Spielstätte wird als Vorgabe verwendet und kann am Termin angepasst werden.</li><li>Warte auf die Prüfung. Ein Ladehinweis bleibt bis zum Ergebnis sichtbar.</li><li>Ist die Belegung möglich, prüfe trotzdem die angezeigte Auslastung.</li><li>Bei Abstimmungsbedarf kontrollierst du die parallel verwendeten Bereiche.</li><li>Bei einem Konflikt wählst du einen vorgeschlagenen freien Zeitraum oder eine angebotene alternative Spielstätte – oder passt den Termin bewusst selbst an.</li></ol><p>Bei Spielen wird der ganze Platz geprüft. Beim Bearbeiten wird der aktuelle Termin aus der Konfliktsuche ausgeschlossen, damit er nicht mit sich selbst kollidiert.</p>${figure('de','location-occupancy','event-check.png','Belegungsprüfung im Kalendertermin mit Bereich und Alternativen','Die Prüfung findet dort statt, wo der verbindliche Kalendertermin angelegt oder geändert wird.')}` },
        { id: 'print-troubleshooting', title: 'Gefilterte Übersicht drucken und fehlende Belegungen prüfen', html: `<p><strong>Übersicht drucken</strong> erzeugt eine PDF für genau den gewählten Zeitraum, Terminfilter und die gewählten Spielstätten. Die Aktion ist ohne Spielstättenauswahl gesperrt. Öffnet sich keine PDF, prüfe die Browserfreigabe für neue Tabs und versuche es nach der Fehlermeldung erneut.</p><ul><li><strong>Termin fehlt:</strong> Prüfe Datum, Uhrzeit, Terminart und Spielstätte im Kalender sowie den aktiven Filter.</li><li><strong>Training fehlt:</strong> Prüfe zusätzlich den Platzbereich. Bei einer teilbaren Fläche muss ein verwendeter Bereich festgelegt sein.</li><li><strong>Falsche Spielstätte:</strong> Bearbeite den Kalendertermin; eine Auswahl in der Belegungsansicht verschiebt keine Buchung.</li><li><strong>Unbekannter Titel:</strong> Private Termine werden absichtlich anonymisiert.</li><li><strong>Heimspielstätte nicht auswählbar:</strong> Prüfe in der Spielstättenverwaltung, ob die Fläche dem Verein als Heimspielstätte zugeordnet ist.</li><li><strong>Unverständlicher Konflikt:</strong> Vergleiche Beginn einschließlich Aufbauzeit, Ende und die Bereiche beider eingeblendeten Termine.</li></ul>` },
      ],
    },
    club: {
      title: 'Vereinsverwaltung – Kaderblick-Dokumentation', heading: 'Vereinsverwaltung nach vollständigen Arbeitswegen', lead: 'Anträge, Mitgliedsakten, Organisation, Beiträge, Bank, Dokumente und Auswertungen sicher von Anfang bis Abschluss bearbeiten.',
      sections: [
        { id: 'overview-access', title: 'Verein wählen, Übersicht lesen und zum richtigen Arbeitsbereich wechseln', html: `<p>Öffne <strong>Vereinsverwaltung</strong> und wähle zuerst den Verein. Die Auswahl gilt für alle folgenden Arbeitsbereiche. Prüfe sie vor jeder Änderung, jedem Export und jedem Finanzvorgang.</p><p>Die Übersicht zeigt aktuelle Zustände und offene Aufgaben. Von dort wechselst du zu <strong>Aufgaben &amp; Anträge</strong>, <strong>Personen &amp; Mitgliedschaften</strong>, <strong>Organisation</strong>, <strong>Finanzen</strong>, <strong>Bank &amp; SEPA</strong>, <strong>Kommunikation &amp; Dokumente</strong>, <strong>Auswertungen</strong> oder <strong>Einrichtung &amp; Datenpflege</strong>. Die globale Suche findet Mitglieder, Mitgliedsnummern, Konten, Forderungen und Dokumente und führt zum passenden Arbeitskontext.</p><p>Bereiche und Aktionen erscheinen nur mit den erforderlichen Vereinsrechten. Lesen, Bearbeiten, Freigeben, Bankbuchung, Dokumentverwaltung und Export können getrennt vergeben sein. Eine ausgeblendete Aktion ist deshalb nicht automatisch ein Ladefehler.</p>${figure('de','club-management','overview.png','Übersicht der Vereinsverwaltung mit Zuständen und Arbeitsbereichen','Die Übersicht zeigt den Vereinszustand und führt in fachlich zusammenhängende Arbeitswege.')}` },
        { id: 'applications', title: 'Aufnahme-, Änderungs- und Verknüpfungsanträge bearbeiten', html: `<p>Unter <strong>Aufgaben &amp; Anträge</strong> stehen offene und erledigte Vorgänge getrennt. Suche nach Person, filtere den Status und sortiere nach ältestem oder neuestem Eingang.</p><h3>Aufnahmeantrag</h3><ol><li>Öffne den Antrag und prüfe Person, Anschrift, gewünschtes Eintrittsdatum, Sprache, Einwilligungen, Vertretung, Nachweise und Beitragsvorschau.</li><li>Vergleiche Warnungen und mögliche vorhandene Mitgliedschaften.</li><li>Stelle bei Unklarheiten eine Rückfrage. Frage, Antwort und Verlauf bleiben am Antrag.</li><li>Nimm den Antrag an oder lehne ihn mit nachvollziehbarem Grund ab. Erst die Annahme erzeugt eine Mitgliedsakte.</li></ol><h3>Änderungsantrag</h3><p>Vergleiche bisherige und beantragte Werte. Du kannst Rückfragen stellen, eine Änderung übernehmen oder begründet ablehnen. Ein Antrag ersetzt nicht unbemerkt zwischenzeitlich geänderte Daten.</p><h3>Verknüpfungsantrag</h3><p>Prüfe Zielmitglied, Empfänger, Beziehung und Gültigkeit. Genehmige oder lehne die Zuordnung oder storniere eine noch nicht beanspruchte Einladung. Ein erledigter Vorgang bleibt im Verlauf sichtbar.</p>${figure('de','club-management','applications.png','Arbeitsliste für Aufnahme-, Änderungs- und Verknüpfungsanträge','Offene Aufgaben und abgeschlossene Vorgänge bleiben nach Art und Status nachvollziehbar.')}` },
        { id: 'members', title: 'Mitglieder anlegen, finden und die vollständige Mitgliedsakte pflegen', html: `<h3>Mitglied finden oder anlegen</h3><p>Öffne <strong>Personen &amp; Mitgliedschaften</strong>. Suche nach Name oder Mitgliedsnummer und filtere aktuelle, ehemalige oder alle Mitgliedschaften. <strong>Mitglied anlegen</strong> erfasst Mitgliedsnummer, Eintritt, persönliche Daten, Kontakt und Anschrift; die verfügbaren Felder richten sich nach deinen Rechten.</p><h3>Mitgliedsakte</h3><ul><li><strong>Überblick:</strong> Mitgliedsnummer, Status, Eintritt, Geburtsdatum, Kontaktweg und Anschrift.</li><li><strong>Kontakt &amp; Zugang:</strong> Kontaktzeiträume, Haushalte, Portalzugänge, Benutzerverknüpfungen sowie Spieler- und Trainerprofile.</li><li><strong>Vereinszugehörigkeit:</strong> Abteilungen, Funktionen, Gremien, Qualifikationen, Ehrungen und weitere zeitbezogene Zuordnungen.</li><li><strong>Beiträge &amp; Zahlungen:</strong> Beitragskonto, beitragspflichtige Person, Forderungen, Zahlungen und Zuordnungen.</li><li><strong>Verlauf &amp; Notizen:</strong> Statushistorie, Austritt, interne Notizen, Einwilligungen, Datenschutzvorgänge und Aktenzusammenführung.</li></ul><p>Ändere einen Status mit Gültigkeitsdatum und Begründung. Ein Austritt ist ein eigener Vorgang. Benutzerkonto, Mitgliedschaft und Sportprofil sind unterschiedliche Datensätze und werden in der Akte miteinander verbunden, nicht gleichgesetzt. Vor einer Aktenzusammenführung zeigt Kaderblick beide Datensätze zum Vergleich. Haushalt und externe Kontaktpersonen werden in der Haushaltsverwaltung gepflegt.</p>${figure('de','club-management','member-record.png','Mitgliedsakte mit getrennten Bereichen für Daten, Zugang, Verein, Finanzen und Verlauf','Die Mitgliedsakte bündelt zusammengehörige Informationen, ohne ihre fachlichen Unterschiede aufzuheben.')}` },
        { id: 'import-quality', title: 'Mitgliederdaten importieren und Qualitätsfunde abarbeiten', html: `<h3>Import vorbereiten und prüfen</h3><ol><li>Öffne <strong>Daten importieren</strong> und wähle ein vorhandenes Zuordnungsprofil oder lege eines an.</li><li>Lade die Mitgliederdatei und ordne jede Quellspalte dem passenden Mitgliedsfeld zu.</li><li>Lege bei Bedarf die Standardzahlungsart fest.</li><li>Prüfe die Vorschau Zeile für Zeile: normalisierte Werte, Pflichtfeldfehler, Abteilungen und mögliche Identitätstreffer.</li><li>Entscheide bei Treffern ausdrücklich zwischen neu anlegen, vorhandenes Mitglied aktualisieren oder überspringen.</li><li>Bestätige die Prüfung und starte erst dann die Übernahme. Der Auftragsstatus zeigt Verarbeitung oder Fehler.</li></ol><p>E-Mail, Mitgliedsnummer und weitere belegte Merkmale unterstützen die Erkennung; ein unsicherer Treffer wird nicht automatisch zusammengeführt. Such- und Entscheidungsfilter helfen bei großen Vorschauen.</p><h3>Datenqualität</h3><p>Öffne <strong>Datenqualität</strong>, aktualisiere die Prüfung und arbeite die Funde mit Begründung und Korrekturhinweis ab. Die Aktion öffnet den passenden Teil der Mitgliedsakte. Prüfe anschließend erneut; das bloße Öffnen eines Fundes behebt ihn nicht.</p>${figure('de','club-management','import.png','Importvorschau mit Feldzuordnung, Treffern und Entscheidungen','Der Import trennt Zuordnung, Vorschau, Identitätsentscheidung und endgültige Übernahme.')}` },
        { id: 'organization-structure', title: 'Abteilungen, Ämter und Gremien definieren und besetzen', html: `<p>Öffne <strong>Organisation</strong> und wähle den Stichtag. Die Übersicht zeigt Abteilungen und Gruppen, Ämter und Funktionen sowie Gremien mit ihren Zuordnungen.</p><ol><li>Lege zuerst die benötigte Definition mit Name, Gültigkeit und Status an.</li><li>Bei Abteilungen kannst du Überordnung, Hauptzuordnung und Beitragsrelevanz festlegen.</li><li>Bei Ämtern und Gremien definierst du die fachliche Struktur, bevor Personen zugeordnet werden.</li><li>Ordne anschließend ein Mitglied mit Beginn, optionalem Ende und gegebenenfalls regulärer oder kommissarischer Funktion zu.</li><li>Bearbeite bestehende Definitionen und Zeiträume, statt historische Zuordnungen zu überschreiben.</li></ol><p><strong>Stand exportieren</strong> verwendet den gewählten Stichtag. Prüfe daher Datum und Verein vor dem Export.</p>${figure('de','club-management','organization.png','Organisationsübersicht mit Abteilungen, Ämtern und Gremien','Definition und personelle Zuordnung erfolgen in einer nachvollziehbaren Reihenfolge.')}` },
        { id: 'organization-people', title: 'Qualifikationen, Nachweise, Ehrungen und Jubiläen verwalten', html: `<h3>Qualifikation mit Nachweis</h3><ol><li>Öffne <strong>Organisation → Qualifikationen</strong>.</li><li>Lege die Qualifikationsart mit Gültigkeit und optionalem Sportbezug an oder öffne eine vorhandene Definition.</li><li>Wähle das Mitglied und den Gültigkeitszeitraum.</li><li>Lade ein Nachweisdokument in das Vereinsarchiv oder wähle ein bereits vorhandenes Dokument.</li><li>Speichere die Zuordnung und prüfe sie anschließend in der Mitgliedsakte.</li></ol><h3>Ehrungen</h3><p>Lege Ehrungsarten an und erfasse Verleihungen mit Person und Datum. Historische Verleihungen bleiben erhalten, auch wenn eine Definition später nicht mehr aktiv verwendet wird.</p><h3>Jubiläen</h3><p>Pflege Jubiläumsregeln und öffne <strong>Anstehende Jubiläen</strong>. Suche die Person, prüfe Datum, Anlass und zugrunde liegende Regel und bearbeite anschließend den fachlich passenden Vorgang. Die Liste ist eine Vorbereitungshilfe und erzeugt nicht automatisch eine Ehrung.</p>` },
        { id: 'contribution-foundations', title: 'Beitragskonten, zahlende Personen und Beitragsordnungen einrichten', html: `<p>Beginne im Finanzbereich mit den Grundlagen, bevor du einen Beitragslauf erzeugst.</p><ol><li>Lege Beitragskonten an und verbinde sie mit dem Mitglied beziehungsweise der zahlenden Person.</li><li>Prüfe Zahlungsart, Währung und gegebenenfalls SEPA-Grundlage.</li><li>Erstelle eine Beitragsordnung mit Code, Name und Gültigkeitszeitraum.</li><li>Ergänze Regeln mit Betrag, Rhythmus, Priorität, Kriterien, anteiliger Berechnung und Gültigkeit.</li><li>Ordne bei Bedarf Abteilungen oder weitere Kriterien zu.</li><li>Prüfe den Entwurf und veröffentliche die passende Version.</li></ol><p>Eine veröffentlichte Ordnung wird nicht direkt überschrieben. Für Änderungen entsteht eine neue Revision. Lösche nur unveröffentlichte, nicht mehr benötigte Entwürfe. Ohne passende veröffentlichte Beitragsordnung kann kein fachlich vollständiger Beitragslauf entstehen.</p>${figure('de','club-management','finance.png','Finanzarbeitsbereich mit Beitragsgrundlagen und Arbeitsablauf','Beitragskonten und veröffentlichte Regeln bilden die Grundlage der späteren Abrechnung.')}` },
        { id: 'billing-dunning-payments', title: 'Beitragsläufe, Mahnläufe und Zahlungen kontrolliert bearbeiten', html: `<h3>Beitragslauf</h3><ol><li>Wähle Periodenbeginn, Periodenende, Berechnungsstichtag, Währung und den Umfang der Mitgliedschaften.</li><li>Erstelle eine unverbindliche Vorschau.</li><li>Prüfe Positionen, Rabatte, Ausnahmen, ausgeschlossene Mitgliedschaften und Warnungen.</li><li>Hole eine zweite Freigabe ein, wenn die Vereinsrichtlinie sie verlangt.</li><li>Schreibe erst den geprüften Lauf fest. Erst dann entstehen verbindliche Forderungen.</li></ol><h3>Mahnwesen</h3><p>Pflege Mahnstufen mit Fälligkeitstagen und Gebühren. Erzeuge einen Mahnlauf als Vorschau, prüfe ausgeschlossene oder gesperrte Forderungen, lasse ihn gegebenenfalls freigeben und schreibe ihn anschließend fest.</p><h3>Zahlung buchen</h3><p>Erfasse Zahlung, Betrag, Währung, Datum und Referenz und ordne sie der passenden Forderung zu. Teilzahlungen, Überzahlungen und manuelle Zuordnungen müssen anhand des angezeigten Restbetrags geprüft werden. Fehlerhafte, noch nicht festgeschriebene Zuordnungen können berichtigt oder entfernt werden.</p>` },
        { id: 'corrections-donations-accounting', title: 'Forderungen korrigieren, Einzug sperren, Spenden belegen und Buchhaltung exportieren', html: `<h3>Korrektur und Sperre</h3><p>Festgeschriebene Forderungen werden nicht überschrieben. Wähle die Forderung und erfasse je nach Sachverhalt Gutschrift, Abschreibung, Erstattung, Storno oder eine andere angebotene Korrektur mit Betrag und Begründung. Bei erforderlicher zweiter Freigabe bleibt der Vorgang bis zur Bestätigung offen. Eine Einzugs- oder Mahnsperre besitzt Enddatum und Grund; sie löscht die Forderung nicht und kann wieder aufgehoben werden.</p><h3>Spenden und Zuwendungsbestätigungen</h3><p>Erfasse Geld- oder Sachspende mit Spender, Anschrift, Zweck, Betrag beziehungsweise Sachangaben und Datum. Hinterlege die gültige Berechtigung des Vereins zur Ausstellung, fordere gegebenenfalls die zweite Freigabe an und erzeuge erst danach die Bestätigung. Storno und Widerruf benötigen eine Begründung und bleiben nachvollziehbar.</p><h3>Buchhaltung und Kassenbuch</h3><p>Lade die CSV-Vorlage für das Kontierungsprofil, fülle Sollkonto, Habenkonto und Kostenstelle je Vorgangstyp, prüfe die Vorschau und aktiviere die gültige Version. Erzeuge anschließend den Export für den gewünschten Zeitraum. Je nach Richtlinie muss eine zweite Person freigeben. Die Kassenbuchübergabe wird vor der endgültigen Verarbeitung ebenfalls als Vorschau geprüft.</p>` },
        { id: 'sepa-mandates-collection', title: 'Bankstammdaten, SEPA-Mandate und Lastschriftläufe verwalten', html: `<p>Unter <strong>Bank &amp; SEPA</strong> führt die Übersicht von den Stammdaten über Mandate und Einzug bis zum Bankabgleich.</p><h3>Stammdaten und Mandate</h3><ol><li>Prüfe Vereinsbankkonto, Kontoinhaber und Gläubigerkennung.</li><li>Lege das Mandat bei der richtigen zahlenden Person mit Referenz, IBAN und Gültigkeit an.</li><li>Erzeuge bei Bedarf das Mandatsformular und lasse es außerhalb der Anwendung ordnungsgemäß bestätigen.</li><li>Markiere widerrufene oder nicht mehr gültige Mandate über den vorgesehenen Vorgang; ändere die Historie nicht still.</li></ol><h3>Lastschriftlauf</h3><ol><li>Wähle Schema, Fälligkeit und die vorgesehenen Forderungen.</li><li>Erzeuge und prüfe die Vorankündigungen.</li><li>Erstelle den Lauf als Vorschau und kontrolliere ausgeschlossene Positionen und Mandatsfehler.</li><li>Hole bei Bedarf die zweite Freigabe ein.</li><li>Schreibe fest und lade erst danach die Bankdatei herunter.</li></ol>${figure('de','club-management','bank.png','Bank- und SEPA-Arbeitsbereich mit Mandaten und Lastschriftlauf','Mandat, Vorankündigung, Vorschau, Freigabe und Bankdatei sind getrennte Arbeitsschritte.')}` },
        { id: 'bank-reconciliation', title: 'Bankdateien importieren, Zahlungen zuordnen und Abstimmungstage abschließen', html: `<h3>Bankimport</h3><ol><li>Wähle das unterstützte CAMT- oder CSV-Format und lade die Datei.</li><li>Prüfe die Vorschau, Duplikate und nicht lesbare Positionen.</li><li>Übernimm den Import. Ein Import allein erzeugt noch keine festgeschriebene Zahlung.</li></ol><h3>Zuordnung und Tagesabschluss</h3><ol><li>Öffne den Abstimmungstag und prüfe vorgeschlagene Treffer.</li><li>Bestätige eindeutige Zuordnungen oder ordne unklare, geteilte und zusammengefasste Zahlungen manuell zu.</li><li>Erfasse Rücklastschrift und Gebühren über die dafür vorgesehene Aktion.</li><li>Kontrolliere offene Positionen und schließe den Tag erst danach.</li></ol><p>Ein abgeschlossener Tag kann nur über die sichtbare Wiederöffnungsaktion und mit passender Berechtigung erneut bearbeitet werden. Automatische Vorschläge ersetzen nicht die fachliche Kontrolle von Betrag, Referenz, Zahler und Forderung.</p>` },
        { id: 'documents', title: 'Dokumentarchiv, Nachweise, Seriendokumente und Vorlagen verwenden', html: `<h3>Archiv</h3><p>Suche nach Dokumenten, öffne oder lade sie herunter und prüfe Dokumentart, Mitgliedsbezug und Status. Berechtigte Personen können PDF-, JPEG- oder PNG-Dateien hochladen und einem fachlichen Vorgang zuordnen. Bei einer fehlgeschlagenen Zustellung zeigt <strong>Wiederherstellen</strong> den betroffenen Vorgang und verlangt eine Bestätigung.</p><h3>Nachweise und Bescheinigungen</h3><p>Erzeuge Mitgliedsbescheinigungen aus der Mitgliedsakte beziehungsweise dem Nachweisbereich. Qualifikationsnachweise werden im Archiv gespeichert und anschließend der Qualifikation zugeordnet; der Upload allein erzeugt keine Qualifikation.</p><h3>Seriendokumente</h3><ol><li>Wähle Vorlage, Sprache und Empfängerkreis.</li><li>Prüfe Vorschau und fehlende Daten.</li><li>Starte die Erstellung und beobachte den Auftragsstatus.</li><li>Kontrolliere erzeugte Dokumente und Zustellungen im Archiv.</li></ol><h3>Vorlagen</h3><p>Lege Dokumentart, Sprache, Inhalt, Platzhalter und Vereinsgestaltung fest. Speichere Änderungen als nachvollziehbare Version und prüfe die Vorschau, bevor die Vorlage für Seriendokumente verwendet wird.</p>${figure('de','club-management','documents.png','Dokumentarbeitsbereich mit Archiv, Nachweisen, Serien und Vorlagen','Archiv, Erzeugung und Vorlagenpflege bleiben getrennte, miteinander verbundene Aufgaben.')}` },
        { id: 'reports', title: 'Kennzahlen prüfen, Listen speichern und Verbandsmeldungen erzeugen', html: `<h3>Übersicht</h3><p>Wähle Auswertungsstichtag und Bewegungszeitraum. Prüfe Mitgliederbestand, Eintritte, Austritte sowie Verteilungen nach Status, Alter, Geschlecht, Abteilung oder Amt. Öffne eine Gruppe, um die zugrunde liegenden Mitglieder zu sehen.</p><h3>Gespeicherte Listen</h3><ol><li>Lege Name und Mitgliederstatus fest.</li><li>Wähle nur benötigte Spalten und Filter.</li><li>Entscheide, ob andere berechtigte Vereinsverwalter die Liste sehen dürfen.</li><li>Speichere, bearbeite oder lösche die Ansicht.</li><li>Exportiere erst nach Prüfung von Empfänger, Zweck und Datenumfang.</li></ol><h3>Verbandsmeldungen</h3><p>Wähle Meldungsart und Zeitraum, prüfe die berechneten Werte und ergänze erforderliche Angaben. Speichere den Stand und exportiere das vorgesehene Format. Falls eine Freigaberichtlinie aktiv ist, bleibt der Export bis zur zweiten Bestätigung gesperrt.</p>${figure('de','club-management','reports.png','Auswertungsbereich mit Kennzahlen, Listen und Meldungen','Kennzahlen führen zu den zugrunde liegenden Personen; Exporte werden bewusst konfiguriert.')}` },
        { id: 'setup-audit', title: 'Module, Aufnahmeverfahren, Zusatzfelder, Datenschutz und Protokoll einrichten', html: `<h3>Module</h3><p>Aktiviere Mitgliederverwaltung, Beiträge, SEPA und Self-Service nur in fachlich sinnvoller Reihenfolge. Mitgliederverwaltung ist Grundlage der weiteren Module; SEPA benötigt Beiträge. Das Deaktivieren eines Grundmoduls kann abhängige Bereiche betreffen und verlangt eine Bestätigung.</p><h3>Aufnahmeverfahren und Satzung</h3><p>Konfiguriere, ob Aufnahmeanträge angeboten werden, welche Angaben und Nachweise erforderlich sind und welche aktuelle Satzungsfassung angezeigt wird. Lade die Satzung als gültiges Dokument hoch und prüfe anschließend den öffentlichen Antrag einschließlich Lesen und PDF-Download.</p><h3>Zusatzfelder</h3><p>Lege Bezeichnung, Typ, Pflichtstatus und Gültigkeit fest. Änderungen an einer bereits verwendeten Definition erfolgen als neue Revision. Werte werden anschließend in der Mitgliedsakte gepflegt.</p><h3>Datenschutz und Export</h3><p>Nutze die vorgesehenen Datenschutzaktionen in der Mitgliedsakte und den vollständigen Vereinsdatenexport nur mit berechtigtem Zweck. Zweite Freigaben können schutzbedürftige Exporte sperren.</p><h3>Änderungsprotokoll</h3><p>Suche nach Zeitraum und Begriff und prüfe Akteur, Aktion, Objekt und Zeitpunkt. Das Protokoll erklärt, was geändert wurde; Korrekturen erfolgen weiterhin im jeweiligen Fachbereich.</p>${figure('de','club-management','settings.png','Einrichtungsbereich mit Modulen, Aufnahme, Zusatzfeldern und Protokoll','Einrichtung und Nachvollziehbarkeit sind eigene Arbeitsbereiche und keine versteckten Formulare in Fachlisten.')}` },
      ],
    },
  },
  en: {
    training: {
      title: 'Training planning – Kaderblick documentation', heading: 'Plan, run and review training completely', lead: 'Manage goals, sequence, team, season and review through connected workflows.',
      sections: [
        { id: 'entry-context', title: 'Open the session, verify context and understand the workflow', html: `<p>Training planning always extends an existing calendar event. Open the training in <strong>Calendar</strong> and select <strong>Plan training</strong>, <strong>Open plan</strong> or <strong>Run</strong>. Check team, date, time, venue and the Draft, Ready or Completed status. Work through <strong>Goal</strong>, <strong>Schedule</strong>, <strong>Team</strong> and <strong>Finish</strong>; mobile shows the current step. Confirm before discarding unsaved changes.</p>${figure('en','training-planning','overview.png','Training event with the planning action','Planning opens the existing training event and does not create a duplicate.')}` },
        { id: 'goals-templates', title: 'Set goals, season links and templates', html: `<p>Record the focus, detailed objective and preparation note, then assign relevant season goals. Applying a team template copies its blocks and equipment into this session; the copy is independent. Save a suitable plan as a new template, rename it or archive it. Template changes require an online connection.</p>${figure('en','training-planning','editor.png','Goal step with season goals and templates','The first step establishes purpose, preparation and reusable foundations.')}` },
        { id: 'schedule-exercises', title: 'Plan blocks, equipment and exercises', html: `<p>Add blocks with title, duration, intensity, objective and instructions. Move, duplicate or remove them and maintain equipment with quantities. Compare total plan duration with the calendar event.</p><p>In the <strong>Exercise library</strong>, search and filter by scope, club, team, age or player count. Review objective, instructions, duration, equipment and setup before adding an exercise. Authorised coaches can create or edit exercises and copy suitable volleyball exercises. Reload before resolving a concurrent edit.</p>${figure('en','training-planning','exercise-library.png','Exercise library with search and exercise details','A library exercise becomes an editable block in the current plan.')}` },
        { id: 'setup', title: 'Create a visual setup', html: `<p>Open the setup action on a block. Select a pitch, add players, coaches, goals, cones, balls, labels and movement paths, then position and edit the elements. Undo and redo are available, and keyboard help explains accessible controls. Save the setup on the block; the run view displays it read-only beside the instructions.</p>${figure('en','training-planning','setup.png','Visual setup editor for a training block','Symbols and paths explain the organisation of the matching block.')}` },
        { id: 'team-publication', title: 'Review attendance and publish player information', html: `<p>The Team step separates internal planning from player-facing information. Review attending, maybe, declined and open responses and adapt group sizes accordingly. Enter the public goal, meeting information, items to bring and notes, then publish deliberately. You may publish an update or withdraw it. Saving the internal draft alone does not make information visible to players. Reload instead of overwriting a publication conflict.</p>${figure('en','training-planning','team.png','Attendance summary and player publication','Only deliberately published information is shown to players.')}` },
        { id: 'week-series', title: 'Review the training week and copy a series', html: `<p>The week overview moves between previous, current and next week and identifies sessions without a plan, drafts, ready plans and completed plans. Open any listed plan directly.</p><p>For a saved plan belonging to a series, preview all destination events, select only the required dates and confirm the copy. Existing plans, skipped dates and conflicts are reported separately; the operation does not silently overwrite the entire series.</p>${figure('en','training-planning','tools.png','Week overview and series tools','Week and series tools connect sessions while preserving existing plans.')}` },
        { id: 'season-collaboration', title: 'Plan the season and collaborate', html: `<p>Maintain season title, dates, phases and goals. Goals may use target dates, observation levels, training evidence or competition values. Record check-ins and review progress. On a version conflict, reload the current season plan.</p><p>For a saved, unfinished plan, assign lead, assistant or setup contributors, add comments and read the history of creation, edits, completion, publication, templates and series transfers.</p>${figure('en','training-planning','season.png','Season plan with phases, goals and progress','Season goals give individual sessions a measurable long-term context.')}` },
        { id: 'run-offline', title: 'Run training on mobile and offline', html: `<p>Mark a plan Ready only after it has a focus and at least one block. Confirm any duration difference. During the session, review context and progress, read the current goal, instructions and setup, record deviations, mark completion and move Previous or Next.</p><p>Offline mode keeps staged progress available. Reconnect before finishing. If online data changed meanwhile, choose deliberately whether to discard the offline changes or apply them; the application does not silently resolve the conflict.</p>${figure('en','training-planning','run-mobile.png','Mobile training run with current block and progress','The run view prioritises the current block and safe progress tracking.')}` },
        { id: 'review-analytics', title: 'Complete, export, analyse and reuse', html: `<p>Add an internal review when completing the session. The summary distinguishes planned, completed and skipped blocks. Reopening requires confirmation. <strong>Print plan / PDF</strong> opens the authenticated plan. Save a useful session as an independent template.</p><p>Analytics cover focuses, deviations, template use and reusable sessions within the authorised team scope. Opening a reusable session shows its source; it is not copied automatically. Empty analytics and loading failures are displayed separately.</p>${figure('en','training-planning','analytics.png','Training analytics with focuses and reusable sessions','Analytics support reuse without exposing another team’s internal plans.')}` },
        { id: 'troubleshooting', title: 'Resolve permissions, loading failures and conflicts', html: `<ul><li>Missing plan action: check event type, team, event status and edit permission.</li><li>Cancelled or deleted event: return to Calendar; do not create a duplicate.</li><li>Version conflict: reload and reapply the intended change deliberately.</li><li>Missing template or exercise: check team, club, sport, filters and archive status.</li><li>Missing series tools: save the draft and verify that the event belongs to a series.</li><li>Players see nothing: publish the player information explicitly.</li><li>Offline finish is blocked: reconnect and resolve queued changes or conflicts.</li><li>Load or PDF failure: use Retry; an error is never represented as an empty workspace.</li></ul><p>Viewing, editing, publishing, collaboration and season planning may require different permissions.</p>` },
      ],
    },
    occupancy: {
      title: 'Venue occupancy – Kaderblick documentation', heading: 'Review occupancy and resolve venue conflicts', lead: 'Understand week and season views, assign pitch areas correctly and resolve overlaps.',
      sections: [
        { id: 'choose-view', title: 'Choose view, period, event type and venues', html: `<p>Venue occupancy reads existing calendar events. Choose Week for operational coordination or Season for a longer period, filter All, Matches or Trainings, and select home venues. Week compares up to four venues; Season can select all home venues. Selections are remembered per view. Loading, error and no-selection states remain explicit.</p>${figure('en','location-occupancy','overview.png','Weekly venue occupancy with selected home venues','Filters and venue selection determine which calendar bookings are compared.')}` },
        { id: 'week-view', title: 'Read weekly occupancy', html: `<p>Move by week or return to Current week. Each day shows free venues or bookings. Matches show teams and competition; trainings show title, team and pitch area; other events use their event type. Private bookings hide their title. Setup time starts before the event and is included in overlap checks. Areas may be whole, half or named segments A, B and C.</p>` },
        { id: 'season-view', title: 'Review season occupancy', html: `<p>Select From and To. Summary cards show total bookings, matches, trainings and days requiring review. Entries are grouped by venue and date with time, booking, participants, area and status. Mobile cards contain the same information and warnings as the desktop table.</p>${figure('en','location-occupancy','season.png','Season occupancy with summary and grouped bookings','The season view reveals utilisation and days that need review.')}` },
        { id: 'conflicts', title: 'Understand overlap and capacity conflicts', html: `<p>An overlap displays both events, the shared time and its cause: a missing area, an unspecified half, a whole-pitch booking, the same segment, or exceeded capacity. Yellow means coordination or clarification is required; red means the stored assignments cannot coexist. Correct the underlying calendar event rather than creating or deleting a separate occupancy record.</p>${figure('en','location-occupancy','conflict.png','Overlapping bookings with time and cause','Both bookings and the specific cause are shown together.')}` },
        { id: 'event-booking', title: 'Assign area and setup time in the calendar event', html: `<p>After selecting a venue while creating or editing a training, choose its named segments or half/whole pitch. Open setup time and adjust the minutes before the event. Wait for the availability check. It reports clear capacity, coordination needs or a conflict and may offer free times or alternative venues. Matches are checked as whole-pitch bookings. While editing, the event is excluded from comparison with itself.</p>${figure('en','location-occupancy','event-check.png','Availability check inside a calendar event','The binding venue assignment is maintained on the calendar event.')}` },
        { id: 'print-troubleshooting', title: 'Print and investigate missing bookings', html: `<p>Print overview creates a PDF for the selected view, period, type and venues and is disabled without a venue. If a booking is missing, check calendar date, time, event type, venue, active filter and training area. A venue is selectable only when assigned as a home venue. Private titles are deliberately hidden. To understand a conflict, compare setup start, event end and both areas.</p>` },
      ],
    },
    club: {
      title: 'Club management – Kaderblick documentation', heading: 'Club management through complete workflows', lead: 'Process requests, records, organisation, fees, banking, documents and reports from start to completion.',
      sections: [
        { id: 'overview-access', title: 'Select the club, read the overview and open the correct workspace', html: `<p>Select the club before any change, export or financial operation. The overview shows current states and open work and links to Requests, People, Organisation, Finance, Bank &amp; SEPA, Documents, Reports and Setup. Global search finds members, numbers, accounts, receivables and documents. Read, edit, approval, banking, document and export permissions are separate; unavailable actions may therefore be hidden.</p>${figure('en','club-management','overview.png','Club management overview and work areas','The overview shows current state and leads into connected workflows.')}` },
        { id: 'applications', title: 'Process membership, change and link requests', html: `<p>Separate open and completed requests, search, filter status and sort by age. For membership requests, review person, address, requested date, language, consents, representation, evidence and fee preview. Ask a question when information is unclear, then accept or reject with a reason; only acceptance creates a member record.</p><p>For change requests, compare old and requested values, ask questions and apply or reject deliberately. For account links, verify member, recipient, relation and validity, then approve, reject or cancel an unclaimed invitation. Conversation and history remain with the request.</p>${figure('en','club-management','applications.png','Worklist for all request types','Open and completed requests remain traceable by type and status.')}` },
        { id: 'members', title: 'Create, find and maintain complete member records', html: `<p>Search by name or member number and filter current, former or all memberships. Creating a member records number, join date, personal data, contact and address.</p><p>The record separates Overview; Contact &amp; access including households, portal, user, player and coach links; Club membership including departments, offices, committees, qualifications and honours; Fees &amp; payments; and History &amp; notes including status, resignation, consents, privacy and merging. Change status with effective date and reason; resignation is a separate workflow. User accounts, memberships and sport profiles remain distinct linked records. Review both records before merging.</p>${figure('en','club-management','member-record.png','Member record with five task-based areas','The record connects related data without treating different record types as identical.')}` },
        { id: 'import-quality', title: 'Import member data and resolve quality findings', html: `<p>Select or create a mapping profile, upload the file, map every source column and set a default payment method if needed. Review normalised values, required-field errors, departments and identity candidates row by row. Decide Create, Update existing or Skip; uncertain matches are never merged automatically. Confirm the review before applying and monitor the background job.</p><p>Refresh Data quality, open each finding from its reason and remediation guidance, correct the linked record and run the check again.</p>${figure('en','club-management','import.png','Import preview with matches and row decisions','Mapping, preview, identity decisions and application are separate steps.')}` },
        { id: 'organization-structure', title: 'Define and staff departments, offices and committees', html: `<p>Select the effective date. Create definitions before assignments. Departments may have a parent, primary and contribution-relevant settings. Define offices and committees, then assign members with start, optional end and regular or acting capacity. Edit dated history instead of overwriting it. Snapshot export uses the selected date.</p>${figure('en','club-management','organization.png','Organisation overview with definitions and assignments','Structure is defined before people are assigned.')}` },
        { id: 'organization-people', title: 'Manage qualifications, evidence, honours and jubilees', html: `<p>Create a qualification type with validity and optional sport, select member and period, then upload evidence to the archive or select an existing document. Saving a file alone does not create the qualification. Record honour types and dated awards. Maintain jubilee rules and review upcoming people by date, occasion and rule; the list prepares work but does not create an award automatically.</p>` },
        { id: 'contribution-foundations', title: 'Set up contribution accounts and plans', html: `<p>Create accounts and connect the member and payer, payment method, currency and SEPA basis. Build a contribution plan with code, name and validity, then rules for amount, interval, priority, criteria, proration and dates. Publish only after review. Published plans are changed through a revision; only unused drafts should be deleted.</p>${figure('en','club-management','finance.png','Finance workspace with contribution foundations','Accounts and published rules are the basis of later billing.')}` },
        { id: 'billing-dunning-payments', title: 'Run billing, dunning and payment posting', html: `<p>For a fee run, select period, calculation date, currency and membership scope, create a preview, review items, discounts, exclusions and warnings, obtain a second approval when required, then post. Only posting creates receivables.</p><p>Configure dunning levels, preview a run, inspect blocked or excluded receivables, approve and post. When posting payments, verify amount, currency, date, reference, allocation and remaining balance; correct or remove unposted allocations.</p>` },
        { id: 'corrections-donations-accounting', title: 'Handle corrections, blocks, donations and accounting', html: `<p>Do not overwrite posted receivables. Record credit, write-off, refund, reversal or another offered adjustment with amount and reason and complete required approval. A collection or dunning block has a reason and end date and does not delete the debt.</p><p>Record monetary or in-kind donations, authorisation details and required approvals before producing a receipt; cancellation and revocation remain traceable. For accounting, complete the CSV mapping profile, preview and activate it, then create the period export. Cash-book handoff also uses a preview.</p>` },
        { id: 'sepa-mandates-collection', title: 'Manage SEPA master data, mandates and collections', html: `<p>Verify the club bank account, owner and creditor identifier. Create a mandate for the correct payer with reference, IBAN and validity, generate its form and record revocation through the dedicated action.</p><p>For collection, choose scheme and due date, create and check pre-notifications, preview the run, inspect exclusions and mandate errors, obtain approval when required, post and only then download the bank file.</p>${figure('en','club-management','bank.png','Bank and SEPA workflow','Mandate, notice, preview, approval and bank file are distinct steps.')}` },
        { id: 'bank-reconciliation', title: 'Import and reconcile bank transactions', html: `<p>Upload supported CAMT or CSV data and review the preview, duplicates and unreadable rows before importing. Import alone does not post a payment. In reconciliation, verify suggestions, confirm clear matches or manually allocate split and combined payments, record returned debits and fees, review open items and close the day. Reopening a closed day requires the dedicated action and permission.</p>` },
        { id: 'documents', title: 'Use the archive, certificates, serial documents and templates', html: `<p>Search, open and download archive items and review type, member and status. Authorised users may upload PDF, JPEG or PNG and recover failed delivery through confirmation. Create member certificates from the relevant workflow. Qualification evidence must be uploaded and then linked to the qualification.</p><p>For serial documents, choose template, language and recipients, review missing data, start the job and check results and delivery. Maintain template type, language, content, placeholders and club design as traceable versions and check the preview.</p>${figure('en','club-management','documents.png','Document archive, certificates, serial documents and templates','Archive, generation and template maintenance remain connected but separate tasks.')}` },
        { id: 'reports', title: 'Review statistics, saved lists and association reports', html: `<p>Select reporting date and movement period, then inspect membership, joins, resignations and distributions and open groups to see their members. For saved lists, choose name, status, required columns, filters and sharing; save, edit, delete or export only after checking purpose and recipients. For association reports, choose type and period, verify calculated values, complete required data and export after any required approval.</p>${figure('en','club-management','reports.png','Reports with statistics, lists and association submissions','Reports connect summary values with their underlying members.')}` },
        { id: 'setup-audit', title: 'Configure modules, applications, fields, privacy and audit', html: `<p>Enable Members, Contributions, SEPA and Self-service in dependency order; disabling a foundation requires confirmation. Configure applications, required data and evidence, upload the current statutes and verify both reading and PDF download in the public application.</p><p>Create custom fields with type, requirement and validity; revise used definitions instead of overwriting them. Use privacy actions and full club export only for an authorised purpose. Search the audit log by period and term to identify actor, action, object and time; corrections still belong in the relevant workspace.</p>${figure('en','club-management','settings.png','Setup area with modules, fields and audit','Configuration and audit remain dedicated work areas.')}` },
      ],
    },
  },
  fr: {
    training: {
      title: 'Planification des entraînements – Documentation Kaderblick', heading: 'Planifier, réaliser et analyser complètement un entraînement', lead: 'Relier objectifs, déroulement, équipe, saison et bilan dans des parcours cohérents.',
      sections: [
        { id:'entry-context', title:'Ouvrir la séance et vérifier le contexte', html:`<p>La planification complète toujours un rendez-vous existant. Ouvre l’entraînement dans le <strong>Calendrier</strong> puis choisis Planifier, Ouvrir ou Réaliser. Vérifie équipe, date, heure, lieu et état Brouillon, Prêt ou Terminé. Suis les quatre étapes Objectif, Déroulement, Équipe et Finalisation. Confirme avant d’abandonner des changements non enregistrés.</p>${figure('fr','training-planning','overview.png','Entraînement avec accès à la planification','La planification conserve le lien avec le rendez-vous existant.')}` },
        { id:'goals-templates', title:'Définir objectifs, saison et modèles', html:`<p>Saisis thème, objectif détaillé et note de préparation, puis associe les objectifs de saison utiles. Un modèle copie blocs et matériel dans une séance indépendante. Enregistre un plan comme nouveau modèle, renomme-le ou archive-le. Ces opérations nécessitent une connexion.</p>${figure('fr','training-planning','editor.png','Étape Objectif avec modèles','Le premier écran fixe le but et les bases réutilisables.')}` },
        { id:'schedule-exercises', title:'Planifier blocs, matériel et exercices', html:`<p>Ajoute titre, durée, intensité, objectif et consignes à chaque bloc. Déplace, duplique ou supprime les blocs, gère le matériel et compare la durée totale au calendrier. Dans la bibliothèque, recherche et filtre par portée, club, équipe, âge ou effectif; contrôle objectif, consignes, durée, matériel et schéma avant l’ajout. Les entraîneurs autorisés peuvent créer, modifier ou copier des exercices. Recharge en cas de conflit.</p>${figure('fr','training-planning','exercise-library.png','Bibliothèque d’exercices','Un exercice devient un bloc modifiable du plan.')}` },
        { id:'setup', title:'Créer le schéma du terrain', html:`<p>Ouvre le schéma d’un bloc, choisis le terrain et ajoute joueurs, entraîneurs, buts, plots, ballons, textes et trajectoires. Positionne les éléments, utilise Annuler/Rétablir et l’aide clavier, puis enregistre. Le schéma reste visible en lecture seule pendant la séance.</p>${figure('fr','training-planning','setup.png','Éditeur du schéma de terrain','Le schéma explique l’organisation du bloc concerné.')}` },
        { id:'team-publication', title:'Contrôler la participation et informer les joueurs', html:`<p>L’étape Équipe distingue la préparation interne des informations publiées. Consulte présents, peut-être, absents et sans réponse. Renseigne objectif public, rendez-vous, matériel à apporter et note, puis publie volontairement. Tu peux republier ou retirer. Enregistrer le brouillon interne ne publie rien; recharge en cas de conflit.</p>${figure('fr','training-planning','team.png','Participation et publication joueurs','Seules les informations explicitement publiées sont visibles des joueurs.')}` },
        { id:'week-series', title:'Consulter la semaine et recopier une série', html:`<p>La vue hebdomadaire affiche les séances sans plan, brouillons, prêtes ou terminées et permet d’ouvrir chacune. Pour une série, enregistre d’abord le brouillon, ouvre l’aperçu, vérifie chaque date, sélectionne les cibles et contrôle le résultat. Les plans existants, dates ignorées et conflits sont signalés séparément.</p>${figure('fr','training-planning','tools.png','Outils de semaine et de série','Le transfert ne remplace pas silencieusement toute la série.')}` },
        { id:'season-collaboration', title:'Planifier la saison et collaborer', html:`<p>Définis titre, dates, phases et objectifs mesurables; ajoute observations intermédiaires et contrôle la progression. Recharge en cas de version concurrente. Pour un plan enregistré non terminé, attribue des responsables Direction, Assistance ou Installation, ajoute des commentaires et consulte l’historique des changements, publications, modèles et transferts.</p>${figure('fr','training-planning','season.png','Plan de saison avec phases et objectifs','Les objectifs relient chaque séance à la saison.')}` },
        { id:'run-offline', title:'Réaliser sur mobile et hors ligne', html:`<p>Avant Prêt, il faut un thème et un bloc; confirme tout écart de durée. Pendant la séance, contrôle le contexte, lis objectif, consignes et schéma, note les écarts, marque le bloc réalisé et navigue entre les blocs. Hors ligne, les changements restent en attente. Reconnecte-toi avant de terminer et choisis explicitement d’appliquer ou d’abandonner les changements lors d’un conflit.</p>${figure('fr','training-planning','run-mobile.png','Réalisation mobile','La vue mobile privilégie le bloc actuel et la progression.')}` },
        { id:'review-analytics', title:'Terminer, exporter, analyser et réutiliser', html:`<p>Ajoute un bilan interne à la fin. Le résumé sépare blocs prévus, réalisés et ignorés; la réouverture demande confirmation. Le PDF fournit le déroulé authentifié. Un plan utile peut devenir un modèle indépendant. Les analyses montrent thèmes, écarts, modèles et séances réutilisables dans le périmètre autorisé; vide et erreur sont distingués.</p>${figure('fr','training-planning','analytics.png','Analyse des entraînements','Les analyses soutiennent la réutilisation sans exposer les autres équipes.')}` },
        { id:'troubleshooting', title:'Résoudre droits, chargements et conflits', html:`<ul><li>Action absente : vérifie type, équipe, état et droit.</li><li>Rendez-vous annulé ou supprimé : retourne au calendrier, sans doublon.</li><li>Conflit : recharge puis réapplique volontairement.</li><li>Modèle ou exercice absent : vérifie filtres, sport et archive.</li><li>Série absente : enregistre et vérifie l’appartenance à une série.</li><li>Joueurs non informés : publie explicitement.</li><li>Fin hors ligne bloquée : reconnecte et synchronise.</li><li>Chargement ou PDF : utilise Réessayer.</li></ul><p>Lecture, modification, publication, collaboration et saison peuvent demander des droits différents.</p>` },
      ],
    },
    occupancy: {
      title:'Occupation des installations – Documentation Kaderblick', heading:'Contrôler l’occupation et résoudre les conflits', lead:'Lire semaine et saison, attribuer les zones et corriger les chevauchements.',
      sections:[
        { id:'choose-view', title:'Choisir vue, période, type et installations', html:`<p>La page utilise les rendez-vous du calendrier. Choisis Semaine ou Saison, Tous, Matchs ou Entraînements et les installations domicile. La semaine compare jusqu’à quatre lieux; la saison peut tous les sélectionner. Sélection, chargement, erreur et absence de choix sont clairement distingués.</p>${figure('fr','location-occupancy','overview.png','Occupation hebdomadaire','Les filtres déterminent les réservations comparées.')}` },
        { id:'week-view', title:'Lire la semaine', html:`<p>Navigue par semaine ou reviens à la semaine actuelle. Chaque jour montre libre ou occupé. Matchs, entraînements et autres rendez-vous affichent heure, participants, type et zone; les réservations privées restent anonymes. Le temps de préparation compte dans le chevauchement. Une zone peut être entière, moitié ou segment A, B ou C.</p>` },
        { id:'season-view', title:'Analyser la saison', html:`<p>Choisis début et fin. Les compteurs indiquent total, matchs, entraînements et jours à vérifier; les lignes sont regroupées par lieu et date. La vue mobile conserve tous les statuts et alertes.</p>${figure('fr','location-occupancy','season.png','Occupation sur la saison','Les jours à vérifier sont visibles sur une période libre.')}` },
        { id:'conflicts', title:'Comprendre les chevauchements', html:`<p>Un chevauchement montre les deux rendez-vous, la période commune et la cause : zone absente, moitié imprécise, terrain entier, même segment ou capacité dépassée. Jaune demande coordination; rouge indique une incompatibilité. Corrige le rendez-vous du calendrier, pas une copie de réservation.</p>${figure('fr','location-occupancy','conflict.png','Réservations en conflit','Les deux réservations et leur cause sont réunies.')}` },
        { id:'event-booking', title:'Réserver dans le calendrier', html:`<p>Dans un entraînement, choisis lieu, segments ou moitié/entier, puis le temps de préparation. Attends le contrôle; il indique disponible, coordination ou conflit et peut proposer horaires et lieux alternatifs. Un match réserve le terrain entier; lors d’une modification, le rendez-vous ne se compare pas à lui-même.</p>${figure('fr','location-occupancy','event-check.png','Contrôle dans le rendez-vous','La réservation obligatoire reste sur le calendrier.')}` },
        { id:'print-troubleshooting', title:'Imprimer et rechercher une réservation manquante', html:`<p>Le PDF reprend vue, période, type et lieux sélectionnés. Sans lieu, l’action est désactivée. Si une entrée manque, vérifie date, heure, type, lieu, filtre et zone. Un lieu doit être défini comme installation domicile. Les titres privés sont masqués. Pour un conflit, compare début avec préparation, fin et zones.</p>` },
      ],
    },
    club: {
      title:'Gestion du club — Documentation Kaderblick', heading:'Gérer le club par parcours complets', lead:'Traiter demandes, dossiers, organisation, cotisations, banque, documents et analyses de bout en bout.',
      sections:[
        { id:'overview-access', title:'Choisir le club et le bon espace', html:`<p>Choisis le club avant toute modification, export ou opération financière. L’aperçu mène vers Demandes, Personnes, Organisation, Finances, Banque &amp; SEPA, Documents, Analyses et Configuration. La recherche trouve membres, numéros, comptes, créances et documents. Lecture, modification, validation, banque, documents et export ont des droits séparés.</p>${figure('fr','club-management','overview.png','Vue d’ensemble de la gestion du club','L’aperçu conduit aux parcours liés.')}` },
        { id:'applications', title:'Traiter adhésions, modifications et liaisons', html:`<p>Sépare ouvert et terminé, recherche, filtre et trie. Pour une adhésion, contrôle personne, adresse, date, langue, consentements, représentation, preuves et cotisation; pose une question puis accepte ou refuse avec motif. Seule l’acceptation crée le dossier. Pour une modification, compare ancien et nouveau. Pour une liaison, vérifie membre, destinataire, relation et validité puis approuve, refuse ou annule l’invitation. Historique et échanges restent attachés.</p>${figure('fr','club-management','applications.png','Liste des demandes','Tous les types et états restent traçables.')}` },
        { id:'members', title:'Créer, rechercher et gérer le dossier membre', html:`<p>Recherche par nom ou numéro et filtre actuels, anciens ou tous. Le dossier sépare Vue d’ensemble; Contact &amp; accès avec foyer, portail, utilisateur, joueur et entraîneur; Appartenance avec sections, fonctions, commissions, qualifications et distinctions; Cotisations &amp; paiements; Historique &amp; notes avec état, sortie, consentements, confidentialité et fusion. Modifie l’état avec date et motif; la sortie est un parcours distinct. Comptes, adhésions et profils sportifs restent des objets liés mais différents. Compare les dossiers avant fusion.</p>${figure('fr','club-management','member-record.png','Dossier membre complet','Les informations liées restent organisées par tâche.')}` },
        { id:'import-quality', title:'Importer et corriger la qualité', html:`<p>Choisis ou crée un profil, charge le fichier, associe les colonnes et la méthode de paiement, puis vérifie valeurs normalisées, erreurs, sections et correspondances. Décide créer, mettre à jour ou ignorer chaque cas et confirme avant l’exécution. Une correspondance incertaine n’est jamais fusionnée automatiquement. Dans Qualité, actualise, ouvre chaque constat, corrige le dossier indiqué puis relance le contrôle.</p>${figure('fr','club-management','import.png','Aperçu d’import','Association, contrôle et exécution sont séparés.')}` },
        { id:'organization-structure', title:'Définir sections, fonctions et commissions', html:`<p>Choisis la date de référence. Crée les définitions avant les affectations. Une section peut avoir parent, indicateur principal et lien de cotisation. Affecte ensuite les membres avec début, fin éventuelle et rôle titulaire ou intérimaire. Conserve les périodes historiques. L’export utilise la date choisie.</p>${figure('fr','club-management','organization.png','Structure du club','La structure précède les affectations.')}` },
        { id:'organization-people', title:'Gérer qualifications, preuves, distinctions et jubilés', html:`<p>Crée le type de qualification, sa validité et son sport, choisis membre et période, puis charge ou sélectionne un justificatif d’archive. Le fichier seul ne crée pas la qualification. Gère types de distinction et remises datées. Les règles de jubilé alimentent la liste des échéances; celle-ci prépare le travail sans créer automatiquement une distinction.</p>` },
        { id:'contribution-foundations', title:'Configurer comptes et règlements de cotisation', html:`<p>Relie compte, membre, payeur, moyen de paiement, devise et base SEPA. Crée le règlement et ses règles de montant, rythme, priorité, critères, prorata et validité. Publie après contrôle. Une version publiée évolue par révision; seuls les brouillons inutilisés sont supprimés.</p>${figure('fr','club-management','finance.png','Bases des cotisations','Comptes et règles publiées précèdent le calcul.')}` },
        { id:'billing-dunning-payments', title:'Calculer, relancer et comptabiliser', html:`<p>Choisis période, date de calcul, devise et périmètre; crée l’aperçu, vérifie lignes, remises, exclusions et alertes, obtiens la seconde validation si nécessaire puis comptabilise. Configure les niveaux de relance et applique le même parcours aperçu–contrôle–validation–comptabilisation. Pour un paiement, vérifie montant, date, référence, affectation et solde; corrige les affectations non comptabilisées.</p>` },
        { id:'corrections-donations-accounting', title:'Corriger, gérer dons et exporter la comptabilité', html:`<p>Ne remplace pas une créance comptabilisée : utilise avoir, abandon, remboursement, annulation ou autre correction avec montant et motif. Un blocage possède motif et échéance sans supprimer la dette. Pour un don, saisis donateur, objet, valeur et autorisation avant le reçu; annulation et révocation restent visibles. Prévisualise et active le profil CSV de comptes avant l’export; le transfert vers le livre de caisse possède aussi un aperçu.</p>` },
        { id:'sepa-mandates-collection', title:'Gérer données SEPA, mandats et prélèvements', html:`<p>Vérifie compte du club, titulaire et identifiant créancier. Crée le mandat du bon payeur avec référence, IBAN et validité, génère le formulaire et utilise l’action dédiée pour la révocation. Pour le prélèvement, choisis schéma et échéance, contrôle les préavis, crée l’aperçu, vérifie exclusions et erreurs, fais valider, comptabilise puis télécharge le fichier bancaire.</p>${figure('fr','club-management','bank.png','Parcours SEPA','Mandat, préavis, aperçu, validation et fichier sont distincts.')}` },
        { id:'bank-reconciliation', title:'Importer et rapprocher la banque', html:`<p>Charge CAMT ou CSV et contrôle aperçu, doublons et lignes illisibles. L’import ne comptabilise pas encore. Dans le rapprochement, confirme les propositions certaines ou répartis manuellement paiements fractionnés ou groupés, enregistre retours et frais, puis clôture la journée. Une journée clôturée exige l’action Rouvrir et le droit correspondant.</p>` },
        { id:'documents', title:'Utiliser archive, justificatifs, séries et modèles', html:`<p>Recherche, ouvre, télécharge ou charge PDF, JPEG et PNG avec leur contexte. Une livraison échouée peut être restaurée après confirmation. Un justificatif de qualification est d’abord archivé puis associé. Pour une série, choisis modèle, langue et destinataires, contrôle les données, lance le traitement et vérifie livraison. Les modèles conservent type, langue, contenu, variables, présentation et versions.</p>${figure('fr','club-management','documents.png','Espace Documents','Archive, production et modèles restent séparés.')}` },
        { id:'reports', title:'Analyser, enregistrer des listes et produire les déclarations', html:`<p>Choisis date et période, consulte effectif, entrées, sorties et répartitions puis ouvre un groupe. Une liste enregistrée définit nom, état, colonnes, filtres et partage; contrôle but et destinataire avant export. Pour une déclaration, choisis type et période, vérifie les calculs, complète les valeurs et exporte après validation éventuelle.</p>${figure('fr','club-management','reports.png','Analyses et listes','Les totaux mènent aux membres concernés.')}` },
        { id:'setup-audit', title:'Configurer modules, adhésion, champs, confidentialité et journal', html:`<p>Active Membres, Cotisations, SEPA et Self-service selon leurs dépendances. Configure formulaire d’adhésion, données, justificatifs et statuts, puis teste lecture et téléchargement PDF. Crée les champs supplémentaires avec type, obligation et validité; révise les définitions utilisées. Utilise confidentialité et export complet uniquement avec un motif autorisé. Le journal identifie acteur, action, objet et date; la correction se fait dans l’espace métier.</p>${figure('fr','club-management','settings.png','Configuration et journal','La configuration reste un espace distinct.')}` },
      ],
    },
  },
  ru: {
    training:{title:'Планирование тренировок — документация Kaderblick',heading:'Полностью спланировать, провести и разобрать тренировку',lead:'Связать цели, ход занятия, команду, сезон и итоги.',sections:[
      {id:'entry-context',title:'Открыть тренировку и проверить контекст',html:`<p>План дополняет существующее событие календаря. Откройте тренировку и выберите планирование, открытие плана или проведение. Проверьте команду, дату, время, место и статус Черновик, Готово или Завершено. Последовательно пройдите Цель, Ход, Команда и Завершение. Подтвердите выход при несохранённых изменениях.</p>${figure('ru','training-planning','overview.png','Событие тренировки с планированием','Второе событие не создаётся.')}`},
      {id:'goals-templates',title:'Задать цели, сезон и шаблон',html:`<p>Укажите тему, точную цель и подготовку, свяжите сезонные цели. Шаблон копирует блоки и инвентарь в независимый план. План можно сохранить новым шаблоном, шаблон переименовать или архивировать. Для этих действий нужна сеть.</p>${figure('ru','training-planning','editor.png','Цели и шаблоны','Первый шаг задаёт основу занятия.')}`},
      {id:'schedule-exercises',title:'Составить блоки, инвентарь и упражнения',html:`<p>Добавьте название, длительность, интенсивность, цель и инструкцию блока. Перемещайте, копируйте и удаляйте блоки; ведите инвентарь и сравнивайте общую длительность с событием. В библиотеке ищите и фильтруйте упражнения, проверяйте цель, игроков, время, инвентарь и схему, затем добавляйте в план. Уполномоченные тренеры создают и редактируют упражнения. При конфликте сначала обновите данные.</p>${figure('ru','training-planning','exercise-library.png','Библиотека упражнений','Упражнение добавляется как редактируемый блок.')}`},
      {id:'setup',title:'Создать схему площадки',html:`<p>Выберите поле и добавьте игроков, тренеров, ворота, конусы, мячи, подписи и траектории. Перемещайте элементы, используйте отмену, повтор и помощь по клавиатуре, затем сохраните схему блока. Во время занятия она доступна только для просмотра.</p>${figure('ru','training-planning','setup.png','Редактор схемы','Схема относится к конкретному блоку.')}`},
      {id:'team-publication',title:'Проверить участие и сообщить игрокам',html:`<p>Шаг Команда разделяет внутренний план и публикацию. Проверьте Да, Возможно, Нет и без ответа. Заполните публичную цель, встречу, что принести и заметку, затем опубликуйте. Публикацию можно обновить или отозвать. Сохранение черновика ничего не публикует; при конфликте обновите данные.</p>${figure('ru','training-planning','team.png','Участие и публикация','Игроки видят только опубликованные сведения.')}`},
      {id:'week-series',title:'Посмотреть неделю и перенести план на серию',html:`<p>Недельный обзор показывает занятия без плана, черновики, готовые и завершённые планы. Для серии сначала сохраните план, откройте предварительный просмотр, проверьте и выберите даты, выполните перенос и изучите результат. Существующие планы, пропуски и конфликты показаны отдельно.</p>${figure('ru','training-planning','tools.png','Неделя и серия','Серия не перезаписывается целиком без проверки.')}`},
      {id:'season-collaboration',title:'Планировать сезон и работать вместе',html:`<p>Задайте название, даты, фазы и измеримые цели, записывайте промежуточные наблюдения и прогресс. При конфликте обновите версию. В сохранённом незавершённом плане назначайте руководителя, помощника и ответственного за установку, добавляйте комментарии и смотрите историю изменений, публикаций, шаблонов и переносов.</p>${figure('ru','training-planning','season.png','План сезона','Цели связывают занятия с сезоном.')}`},
      {id:'run-offline',title:'Провести с телефона и офлайн',html:`<p>Для статуса Готово нужны тема и блок; подтвердите разницу длительности. Во время занятия читайте цель, инструкцию и схему, записывайте отклонения, отмечайте выполнение и переходите между блоками. Офлайн-изменения ждут синхронизации. Перед завершением подключитесь и при конфликте осознанно примените либо отбросьте их.</p>${figure('ru','training-planning','run-mobile.png','Мобильное проведение','На экране остаются текущий блок и прогресс.')}`},
      {id:'review-analytics',title:'Завершить, выгрузить и проанализировать',html:`<p>При завершении добавьте внутренние итоги. Сводка различает запланированное, выполненное и пропущенное; повторное открытие требует подтверждения. PDF содержит план, а полезную тренировку можно сохранить отдельным шаблоном. Аналитика показывает темы, отклонения, шаблоны и повторно используемые занятия в разрешённой команде.</p>${figure('ru','training-planning','analytics.png','Аналитика тренировок','Пустые данные и ошибка загрузки различаются.')}`},
      {id:'troubleshooting',title:'Решить проблемы прав, загрузки и конфликтов',html:`<ul><li>Нет действия: проверьте тип, команду, статус и право.</li><li>Событие отменено или удалено: вернитесь в календарь, не создавайте копию.</li><li>Конфликт версии: обновите и повторите нужное изменение.</li><li>Нет шаблона или упражнения: проверьте команду, клуб, спорт, фильтр и архив.</li><li>Нет серии: сохраните черновик и проверьте серию события.</li><li>Игрок ничего не видит: выполните публикацию.</li><li>Офлайн-завершение заблокировано: подключитесь и синхронизируйте.</li></ul><p>Просмотр, изменение, публикация, совместная работа и сезон могут требовать разных прав.</p>`},
    ]},
    occupancy:{title:'Занятость площадок — документация Kaderblick',heading:'Проверка занятости и устранение конфликтов',lead:'Понять неделю и сезон, правильно назначить зоны и устранить пересечения.',sections:[
      {id:'choose-view',title:'Выбрать вид, период, тип и площадки',html:`<p>Раздел использует события календаря. Выберите Неделю или Сезон, Все, Матчи или Тренировки и домашние площадки. Неделя сравнивает до четырёх, сезон — все. Выбор запоминается. Загрузка, ошибка и отсутствие выбора показаны явно.</p>${figure('ru','location-occupancy','overview.png','Недельная занятость','Фильтры задают сравниваемые события.')}`},
      {id:'week-view',title:'Прочитать недельную занятость',html:`<p>Переходите по неделям или вернитесь к текущей. День показывает свободные места или события. Матчи, тренировки и другие события содержат время, участников, тип и зону; частные названия скрыты. Подготовка учитывается до начала. Зона бывает целой, половиной или сегментом A, B, C.</p>`},
      {id:'season-view',title:'Проанализировать сезон',html:`<p>Задайте даты. Счётчики показывают всего, матчи, тренировки и дни для проверки; записи сгруппированы по месту и дню. На телефоне сохраняются все статусы.</p>${figure('ru','location-occupancy','season.png','Сезонная занятость','Видны дни, требующие проверки.')}`},
      {id:'conflicts',title:'Понять пересечения',html:`<p>Показаны оба события, общий период и причина: нет зоны, не указана половина, занято всё поле, одинаковый сегмент или превышена вместимость. Жёлтый требует согласования, красный означает несовместимость. Исправляйте исходное событие календаря.</p>${figure('ru','location-occupancy','conflict.png','Конфликт площадки','Причина показана вместе с обоими событиями.')}`},
      {id:'event-booking',title:'Забронировать в календаре',html:`<p>В событии выберите площадку, сегменты или половину/всё поле и время подготовки. Дождитесь проверки: доступно, нужна координация или конфликт; можно выбрать предложенное время или другое место. Матч занимает всё поле, редактируемое событие не конфликтует само с собой.</p>${figure('ru','location-occupancy','event-check.png','Проверка в событии','Бронирование хранится в календаре.')}`},
      {id:'print-troubleshooting',title:'Печать и поиск пропущенных записей',html:`<p>PDF использует выбранные вид, даты, тип и площадки. Без площадки кнопка недоступна. При отсутствии записи проверьте дату, время, тип, место, фильтр и зону. Место должно быть домашним. Частные названия скрыты. Для конфликта сравните подготовку, окончание и зоны.</p>`},
    ]},
    club:{title:'Управление клубом — документация Kaderblick',heading:'Управление клубом по полным рабочим процессам',lead:'Заявки, карточки, структура, взносы, банк, документы и отчёты от начала до результата.',sections:[
      {id:'overview-access',title:'Выбрать клуб и рабочий раздел',html:`<p>Перед изменением, экспортом или финансовой операцией выберите клуб. Обзор ведёт к Заявкам, Людям, Организации, Финансам, Банку и SEPA, Документам, Отчётам и Настройке. Общий поиск находит участников, номера, счета, требования и документы. Права чтения, изменения, утверждения, банка, документов и экспорта разделены.</p>${figure('ru','club-management','overview.png','Обзор управления клубом','Обзор показывает состояние и связанные задачи.')}`},
      {id:'applications',title:'Обработать вступление, изменения и привязки',html:`<p>Разделяйте открытые и завершённые, ищите, фильтруйте и сортируйте. Во вступлении проверьте человека, адрес, дату, язык, согласия, представителя, документы и расчёт; задайте вопрос, примите или отклоните с причиной. Только принятие создаёт карточку. В изменении сравните старое и новое. В привязке проверьте участника, получателя, отношение и срок; подтвердите, отклоните или отмените приглашение. Переписка и история сохраняются.</p>${figure('ru','club-management','applications.png','Список заявок','Все типы и статусы остаются видимыми.')}`},
      {id:'members',title:'Создать, найти и вести карточку участника',html:`<p>Ищите по имени или номеру и фильтруйте действующих, бывших или всех. Карточка разделяет основные данные; контакты и доступ с семьёй, порталом, аккаунтом, игроком и тренером; клубные связи; взносы; историю и заметки со статусом, выходом, согласиями, приватностью и объединением. Статус меняется с датой и причиной, выход — отдельный процесс. Аккаунт, членство и спортивный профиль связаны, но не тождественны. Перед объединением сравните обе карточки.</p>${figure('ru','club-management','member-record.png','Полная карточка участника','Данные организованы по задачам.')}`},
      {id:'import-quality',title:'Импортировать и исправить качество',html:`<p>Выберите профиль, файл и соответствие колонок, проверьте нормализованные значения, ошибки, отделения и совпадения. Для каждой строки решите: создать, обновить или пропустить, затем подтвердите запуск. Сомнительные совпадения не объединяются автоматически. В Качестве обновите список, откройте находку, исправьте карточку и проверьте снова.</p>${figure('ru','club-management','import.png','Предпросмотр импорта','Сопоставление, проверка и применение разделены.')}`},
      {id:'organization-structure',title:'Создать отделения, должности и комитеты',html:`<p>Выберите дату. Сначала создайте определения, затем назначения. Для отделения задаются родитель, основное и взносное значение. Назначайте участника с началом, окончанием и постоянной или временной ролью; сохраняйте историю. Экспорт использует выбранную дату.</p>${figure('ru','club-management','organization.png','Структура клуба','Сначала структура, затем люди.')}`},
      {id:'organization-people',title:'Квалификации, подтверждения, награды и юбилеи',html:`<p>Создайте тип квалификации, срок и спорт, выберите человека и период, загрузите или выберите документ. Один файл квалификацию не создаёт. Ведите типы наград и даты вручения. Правила юбилеев формируют список будущих дат, но не создают награду автоматически.</p>`},
      {id:'contribution-foundations',title:'Настроить счета и правила взносов',html:`<p>Свяжите счёт, участника, плательщика, способ, валюту и SEPA. Создайте положение и правила суммы, периода, приоритета, критериев, пропорции и срока. Публикуйте после проверки. Опубликованное меняется новой редакцией; удаляются только ненужные черновики.</p>${figure('ru','club-management','finance.png','Основы взносов','Правила предшествуют расчёту.')}`},
      {id:'billing-dunning-payments',title:'Рассчитать, напомнить и провести платежи',html:`<p>Выберите период, расчётную дату, валюту и охват, создайте предпросмотр, проверьте строки, скидки, исключения и предупреждения, получите второе утверждение и проведите. Для напоминаний настройте уровни и повторите предпросмотр–проверку–утверждение–проведение. При платеже проверьте сумму, дату, ссылку, распределение и остаток.</p>`},
      {id:'corrections-donations-accounting',title:'Исправления, пожертвования и бухгалтерия',html:`<p>Проведённое требование не переписывается: создайте кредит, списание, возврат или отмену с причиной. Блокировка имеет причину и дату и не удаляет долг. Для пожертвования укажите жертвователя, цель, значение и полномочие до квитанции; отмена сохраняется. Проверьте и активируйте CSV-профиль счетов до экспорта; передача в кассовую книгу тоже имеет предпросмотр.</p>`},
      {id:'sepa-mandates-collection',title:'Мандаты SEPA и списания',html:`<p>Проверьте счёт клуба, владельца и идентификатор кредитора. Создайте мандат правильного плательщика с ссылкой, IBAN и сроком, сформируйте форму и используйте отдельный отзыв. Для списания выберите схему и дату, проверьте уведомления и предпросмотр, исключения и ошибки, получите утверждение, проведите и затем скачайте файл.</p>${figure('ru','club-management','bank.png','Процесс SEPA','Шаги разделены.')}`},
      {id:'bank-reconciliation',title:'Импортировать и сверить банк',html:`<p>Загрузите CAMT или CSV и проверьте предпросмотр, дубликаты и ошибки. Импорт ещё не проводит платёж. Подтвердите ясные совпадения или вручную распределите разделённые и объединённые платежи, запишите возвраты и закройте день. Для повторной работы день нужно явно открыть.</p>`},
      {id:'documents',title:'Архив, подтверждения, серии и шаблоны',html:`<p>Ищите, открывайте, скачивайте и загружайте PDF, JPEG и PNG с контекстом. Ошибочную доставку можно восстановить после подтверждения. Документ квалификации сначала архивируется, затем связывается. Для серии выберите шаблон, язык и получателей, проверьте данные и результат. Шаблоны хранят тип, язык, содержимое, переменные, оформление и версии.</p>${figure('ru','club-management','documents.png','Документы','Архив, создание и шаблоны разделены.')}`},
      {id:'reports',title:'Показатели, списки и отчёты ассоциации',html:`<p>Выберите дату и период, изучите состав, вступления, выходы и распределения и откройте группу. Список задаёт имя, статус, колонки, фильтры и общий доступ; перед экспортом проверьте цель. Для отчёта выберите тип и период, проверьте расчёт, дополните сведения и экспортируйте после утверждения.</p>${figure('ru','club-management','reports.png','Отчёты и списки','Итоги связаны с участниками.')}`},
      {id:'setup-audit',title:'Модули, заявления, поля, приватность и аудит',html:`<p>Включайте Участников, Взносы, SEPA и Самообслуживание с учётом зависимостей. Настройте заявление, обязательные данные, документы и устав и проверьте чтение и PDF. Дополнительные поля имеют тип, обязательность и срок; используемые определения меняются редакцией. Приватность и полный экспорт требуют законной цели. Аудит показывает автора, действие, объект и время; исправление выполняется в рабочем разделе.</p>${figure('ru','club-management','settings.png','Настройка и аудит','Настройки находятся отдельно от рабочих списков.')}`},
    ]},
  },
  zh_Hans: {
    training:{title:'训练计划 – Kaderblick 文档',heading:'完整规划、执行和复盘训练',lead:'在连续流程中管理目标、流程、球队、赛季和复盘。',sections:[
      {id:'entry-context',title:'打开训练并核对上下文',html:`<p>训练计划始终扩展已有日历日程。打开训练并选择计划、打开计划或执行。核对球队、日期、时间、场地以及草稿、就绪或已完成状态。依次完成目标、流程、球队和结束四步。离开未保存的更改前需确认。</p>${figure('zh_Hans','training-planning','overview.png','带计划入口的训练日程','不会创建重复日程。')}`},
      {id:'goals-templates',title:'设置目标、赛季关联和模板',html:`<p>填写重点、详细目标和准备说明，并关联赛季目标。模板会把区块和器材复制成独立计划。可把计划保存为新模板、重命名或归档；这些操作需要联网。</p>${figure('zh_Hans','training-planning','editor.png','目标和模板步骤','第一步确定训练基础。')}`},
      {id:'schedule-exercises',title:'规划区块、器材和练习',html:`<p>为区块填写标题、时长、强度、目标和说明；移动、复制或删除区块，维护器材数量并比较总时长。练习库可按范围、俱乐部、球队、年龄和人数筛选；检查目标、说明、时长、器材和场地布置后加入计划。有权限的教练可新建或编辑练习。冲突时先重新加载。</p>${figure('zh_Hans','training-planning','exercise-library.png','练习库','练习会成为可编辑区块。')}`},
      {id:'setup',title:'创建图形化场地布置',html:`<p>选择场地并添加球员、教练、球门、标志桶、球、文字和移动路线。可移动和编辑元素、撤销或重做，并查看键盘帮助。保存到区块后，执行训练时以只读方式显示。</p>${figure('zh_Hans','training-planning','setup.png','场地布置编辑器','图形说明对应区块的组织方式。')}`},
      {id:'team-publication',title:'检查出勤并发布球员信息',html:`<p>球队步骤把内部计划与球员信息分开。查看参加、可能、缺席和未回复，填写公开目标、集合信息、携带物品和备注后主动发布。可更新或撤回。仅保存内部草稿不会发布；冲突时先加载当前版本。</p>${figure('zh_Hans','training-planning','team.png','出勤与球员发布','球员只看到明确发布的内容。')}`},
      {id:'week-series',title:'查看本周并复制到系列日程',html:`<p>周视图显示无计划、草稿、就绪和已完成的训练并可直接打开。系列复制前先保存，预览每个目标日期，选择需要的日期并检查结果。已有计划、跳过项和冲突分别显示，不会静默覆盖整个系列。</p>${figure('zh_Hans','training-planning','tools.png','周和系列工具','复制前会逐个检查目标日程。')}`},
      {id:'season-collaboration',title:'规划赛季并协作',html:`<p>设置标题、日期、阶段和可衡量目标，记录中间观察并查看进度；版本冲突时重新加载。已保存且未完成的计划可分配负责人、助理和布置人员，添加评论，并查看修改、发布、模板和系列复制历史。</p>${figure('zh_Hans','training-planning','season.png','赛季计划','赛季目标连接每次训练。')}`},
      {id:'run-offline',title:'在手机和离线状态下执行',html:`<p>标记就绪前必须有重点和至少一个区块，并确认时长差异。执行时查看目标、说明和布置，记录偏差、标记完成并切换区块。离线更改等待同步；结束前重新联网，冲突时明确选择应用或放弃。</p>${figure('zh_Hans','training-planning','run-mobile.png','移动端执行','当前区块和进度保持突出。')}`},
      {id:'review-analytics',title:'完成、导出、分析和复用',html:`<p>完成时填写内部复盘。摘要区分计划、完成和跳过的区块；重新打开需要确认。PDF 提供认证后的流程计划，优秀计划可保存为独立模板。分析显示授权球队范围内的重点、偏差、模板和可复用训练，并区分空数据与加载错误。</p>${figure('zh_Hans','training-planning','analytics.png','训练分析','分析帮助复用且不泄露其他球队计划。')}`},
      {id:'troubleshooting',title:'处理权限、加载和冲突',html:`<ul><li>没有计划操作：检查类型、球队、状态和权限。</li><li>日程取消或删除：返回日历，不要创建副本。</li><li>版本冲突：重新加载后再应用更改。</li><li>模板或练习缺失：检查球队、俱乐部、运动、筛选和归档。</li><li>没有系列工具：先保存并确认日程属于系列。</li><li>球员看不到：明确发布球员信息。</li><li>离线无法结束：联网并解决同步。</li></ul><p>查看、编辑、发布、协作和赛季计划可能需要不同权限。</p>`},
    ]},
    occupancy:{title:'场地占用 – Kaderblick 文档',heading:'检查场地占用并解决冲突',lead:'理解周和赛季视图，正确分配区域并处理重叠。',sections:[
      {id:'choose-view',title:'选择视图、时间、类型和场地',html:`<p>本页读取日历日程。选择周或赛季、全部/比赛/训练以及主场场地。周视图最多比较四个，赛季可选择全部。系统分别记住选择，并明确显示加载、错误和未选择状态。</p>${figure('zh_Hans','location-occupancy','overview.png','每周场地占用','筛选决定比较哪些日程。')}`},
      {id:'week-view',title:'查看每周占用',html:`<p>按周前后移动或返回当前周。每天显示空闲或占用。比赛、训练和其他日程显示时间、参与者、类型和区域；私密标题会隐藏。准备时间计入重叠。区域可为全场、半场或 A、B、C 分区。</p>`},
      {id:'season-view',title:'分析赛季占用',html:`<p>设置起止日期。统计显示总数、比赛、训练和需检查日期，记录按场地和日期分组；手机视图保留全部状态与警告。</p>${figure('zh_Hans','location-occupancy','season.png','赛季占用','可识别需要检查的日期。')}`},
      {id:'conflicts',title:'理解时间重叠',html:`<p>重叠会同时显示两个日程、共同时间和原因：区域缺失、半场不明确、全场占用、相同分区或超出容量。黄色表示需要协调，红色表示当前记录无法并存。应修改原日历日程。</p>${figure('zh_Hans','location-occupancy','conflict.png','场地冲突','两个日程和原因一起显示。')}`},
      {id:'event-booking',title:'在日历中预订场地',html:`<p>在训练日程中选择场地、分区或半场/全场以及准备时间，并等待检查。结果为可用、需协调或冲突，还可提供替代时间和场地。比赛按全场检查；编辑时不会与自身冲突。</p>${figure('zh_Hans','location-occupancy','event-check.png','日历中的占用检查','正式预订保存在日历日程。')}`},
      {id:'print-troubleshooting',title:'打印并排查缺失占用',html:`<p>PDF 使用当前视图、日期、类型和场地；未选场地时禁用。记录缺失时检查日期、时间、类型、场地、筛选和区域。场地必须设为主场。私密标题会隐藏。冲突排查要比较准备开始、结束和双方区域。</p>`},
    ]},
    club:{title:'俱乐部管理 – Kaderblick 文档',heading:'按完整工作流程管理俱乐部',lead:'从开始到完成处理申请、会员档案、组织、会费、银行、文档和报表。',sections:[
      {id:'overview-access',title:'选择俱乐部和正确工作区',html:`<p>任何修改、导出或财务操作前先选择俱乐部。概览连接申请、人员、组织、财务、银行与 SEPA、文档、报表和设置。全局搜索可查会员、编号、账户、应收款和文档。读取、编辑、审批、银行、文档和导出权限彼此独立。</p>${figure('zh_Hans','club-management','overview.png','俱乐部管理概览','概览显示状态并进入连续流程。')}`},
      {id:'applications',title:'处理入会、资料变更和账户关联',html:`<p>区分待办和已完成，可搜索、筛选和排序。入会申请要检查人员、地址、日期、语言、同意、代理人、证明和会费预览；不清楚时提问，再接受或说明理由拒绝。只有接受才创建档案。资料变更要比较旧值和新值。关联申请要检查会员、接收人、关系和有效期，再批准、拒绝或取消未领取邀请。对话与历史保留。</p>${figure('zh_Hans','club-management','applications.png','申请工作列表','所有类型和状态可追溯。')}`},
      {id:'members',title:'新建、查找和维护完整会员档案',html:`<p>按姓名或会员号搜索，并筛选当前、历史或全部。档案分为概览；联系方式与访问，包括家庭、门户、用户、球员和教练关联；俱乐部归属；会费与付款；历史与备注，包括状态、退会、同意、隐私和合并。状态变更含生效日期和理由，退会是独立流程。用户账户、会员资格和运动档案相互关联但不相同；合并前比较两份档案。</p>${figure('zh_Hans','club-management','member-record.png','完整会员档案','相关信息按任务组织。')}`},
      {id:'import-quality',title:'导入并修正数据质量',html:`<p>选择或新建映射配置，上传文件并映射列，检查规范化值、错误、部门和可能匹配。逐行选择新建、更新或跳过，确认后再执行；不确定匹配不会自动合并。数据质量中刷新问题，打开提示的档案，修正后重新检查。</p>${figure('zh_Hans','club-management','import.png','导入预览','映射、检查、匹配决定和应用彼此分开。')}`},
      {id:'organization-structure',title:'定义部门、职务和委员会',html:`<p>选择截止日期，先创建定义再分配人员。部门可设置上级、主要和会费相关属性；人员分配包含开始、可选结束和正式或代理职务。保留历史时间段。组织快照导出使用所选日期。</p>${figure('zh_Hans','club-management','organization.png','俱乐部组织','先建结构，再分配人员。')}`},
      {id:'organization-people',title:'管理资质、证明、荣誉和周年纪念',html:`<p>创建资质类型、有效期和运动，选择会员和时间，再上传或选择档案证明；单独上传不会创建资质。维护荣誉类型和授予日期。周年规则生成即将到期列表，但不会自动创建荣誉。</p>`},
      {id:'contribution-foundations',title:'设置会费账户和会费方案',html:`<p>关联账户、会员、付款人、方式、币种和 SEPA 基础。创建方案及金额、周期、优先级、条件、按比例和有效期规则。检查后发布。已发布方案通过新版本修改；只删除未使用草稿。</p>${figure('zh_Hans','club-management','finance.png','会费基础','账户和规则是计算基础。')}`},
      {id:'billing-dunning-payments',title:'计算会费、催缴并登记付款',html:`<p>选择期间、计算日、币种和会员范围，生成预览，检查项目、优惠、排除和警告，按需取得第二审批后入账。催缴先配置级别，再按预览、检查、审批、入账处理。付款要核对金额、日期、参考号、分配和余额；未入账分配可修正。</p>`},
      {id:'corrections-donations-accounting',title:'处理更正、捐赠和会计',html:`<p>已入账应收款不得覆盖，应以贷项、核销、退款或冲销并填写金额和理由。暂停催收有理由和结束日期，不删除债务。捐赠先记录捐赠人、用途、价值和授权，再生成证明；取消和撤销保留记录。会计 CSV 映射先预览并启用，再导出；现金簿移交也先预览。</p>`},
      {id:'sepa-mandates-collection',title:'管理 SEPA 授权和扣款',html:`<p>核对俱乐部账户、账户持有人和债权人标识。为正确付款人创建含参考号、IBAN 和有效期的授权，生成表单，并通过专用操作撤销。扣款要选择方案和到期日，检查预先通知和预览、排除及授权错误，按需审批，入账后才下载银行文件。</p>${figure('zh_Hans','club-management','bank.png','SEPA 流程','授权、通知、预览、审批和文件是独立步骤。')}`},
      {id:'bank-reconciliation',title:'导入并核对银行流水',html:`<p>上传 CAMT 或 CSV，检查预览、重复和错误行。导入本身不会登记付款。确认明确匹配，或手动分配拆分和合并付款，登记退票和费用，最后关闭对账日。已关闭日期需用重新打开操作并具备权限。</p>`},
      {id:'documents',title:'使用档案、证明、批量文档和模板',html:`<p>搜索、打开、下载或上传带上下文的 PDF、JPEG 和 PNG。失败的送达可确认后恢复。资质证明先归档再关联。批量文档要选择模板、语言和接收人，检查数据、启动任务并核对结果。模板保存类型、语言、内容、占位符、样式和版本。</p>${figure('zh_Hans','club-management','documents.png','文档工作区','档案、生成和模板维护分开。')}`},
      {id:'reports',title:'查看统计、保存列表和生成协会报表',html:`<p>选择统计日期和变动期间，查看会员数、加入、退出和分布，并打开分组。保存列表时设置名称、状态、列、筛选和共享；导出前检查用途和接收人。协会报表选择类型和期间，核对计算并补充数据，按需审批后导出。</p>${figure('zh_Hans','club-management','reports.png','报表和列表','汇总数值可追溯到会员。')}`},
      {id:'setup-audit',title:'配置模块、入会、字段、隐私和审计',html:`<p>按依赖顺序启用会员、会费、SEPA 和自助服务。配置入会表单、必填资料、证明和章程，并验证在线阅读和 PDF。自定义字段包含类型、必填和有效期；已使用定义通过新版本修改。隐私操作和完整导出必须有授权目的。审计日志显示操作人、动作、对象和时间；更正仍在对应工作区完成。</p>${figure('zh_Hans','club-management','settings.png','设置和审计','配置是独立工作区。')}`},
    ]},
  },
};

for (const [locale, pages] of Object.entries(localized)) {
  const target = join(root, 'content', locale);
  await writeFile(join(target, 'training-planning.json'), `${JSON.stringify(documentFor(pages.training), null, 4)}\n`);
  await writeFile(join(target, 'location-occupancy.json'), `${JSON.stringify(documentFor(pages.occupancy), null, 4)}\n`);
  await writeFile(join(target, 'club-management.json'), `${JSON.stringify(documentFor(pages.club), null, 4)}\n`);
}

console.log('Complete workflow documentation written.');
